INSERT INTO `keterangan` (`id_ket`, `id_iku`, `id_triwulan`, `id_prodi`, `progres`, `kendala`, `strategi`) VALUES
(69, 1, 1, 1, 'IKU ini merupakan data capaian untuk lulusan yang mendapatkan pekerjaan dengan masa tunggu kurang dari 6 (enam) bulan dan gaji lebih dari 1,2 (satu koma dua) kali Upah Minimum Regional (UMR), lulusan yang melanjutkan studi di Perguruan Tinggi Negeri (PTN) Akademik Mendapatkan surat penerimaan untuk melanjutkan proses pembelajaran di program studi S2/S2 terapan, S3/S3 terapan di dalam negeri atau luar negeri dalam jangka waktu kurang dari 12 (dua belas) bulan setelah lulus serta lulusan yang mulai bekerja dalam waktu kurang dari 6 (enam) bulan setelah lulus dan berpenghasilan lebih dari 1,2 (satu koma dua) kali UMR. untuk capaian di TW 1 ini Poltesa berhasil mencapai 20.84% dari yang ditargetkan di TW 1 sebesar 20%. Dari total 379 orang lulusan dari 9 prodi yang di wisuda pada akhir tahun 2022 kemarin ada sebanyak 59 orang yang telah berhasil mendapatkan pekerjaan, 1 orang yang melanjutkan studi, dan ada 19 orang yang menjadi wiraswasta. Adapun upaya yang telah dilakukan dalam mencapai IKK ini diantaranya: 1. Melakukan Bembekalan kepada wisudawan terkait pentingnya memberikan data di aplikasi tracer study 2. Meningkatkan pelayanan pada aplikasi tracer study 3. Menjadikan bukti pengisian tracer study sebagai syarat dalam pengambilan ijazah 4. Mengaktifkan grub WA alumni. ', 'Kendala yang dialami dalam melakukan pengukuran pada IKK ini diantaranya: 1. Adanya sedikit masalah pada aplikasi tracer study yang disebabkan oleh pemindahan server sehingga ada jeda waktu yang menyebabkan tim gagal dalam menarik data 2. Masih banyak alumni yang belum mengambil ijazah 3. Adanya alumni yang lost contak atau berganti nomor', 'Adapun tindak lanjut yang dilakukan dalam mengatasi kendala-kendala tersebut sesuai dengan arahan pimpinan pada saat rapat pengukuran kinerja diantaranya: 1. Meminta tim developer dan tim TIK untuk segera menyelesaikan proses pemindahan server aplikasi tracer study, sehingga pengisian data dan penarikan data dari aplikasi tracer bisa maksimal 2. Melalui WA grub alumni, para kaprodi diminta untuk menghimbau alumni untuk segera melakukan pengambilan ijazah dan meminta melakukan update jika ada perubahan nomor Hp dan status pekerjaan atau usaha.'),
(70, 2, 1, 1, 'IKU ini merupakan data capaian untuk Mahasiswa yang mendapatkan paling sedikit 20 (dua puluh) sks dari kegiatan di luar kampus (dengan dosen pembimbing), sesuai dengan Buku Panduan Merdeka Belajar serta Berprestasi dalam kompetisi atau lomba paling rendah tingkat nasional. Adapun cara perhitungannya adalah jumlah mahasiswa yang Mahasiswa yang mendapatkan paling sedikit 20 (dua puluh) sks dari kegiatan di luar dan Berprestasi dalam kompetisi atau lomba paling rendah tingkat nasional dibagi dengan jumlah mahasiswa aktif ditahun 2023 di kali 100%. untuk capaian di TW 1 ini Poltesa berhasil mencapai 0,45 % dari yang ditargetkan sebesar 0,25%. untuk saat ini berdasarkan data pada PDDIKTI ada sekitar 1.980 mahasiswa aktif yang ada di lingkungan Poltesa. dari 1.980 mahasiswa aktif tersebut ada sebanyak 8 orang mahasiswa yang telah menghabiskan paling sedikit 20 sks diluar kampus. Yaitu 1 orang dari prodi APK atas nama Bintang Rahasia Ramadhan Magang di luar negeri di Restoran Pengolahan Produk Perikanan, 2 orang dari prodi MBP atas nama Juanda dan Agung Dirgantoro Mandala Putra Magang dan Studi Independen Bersertifikat Batch 4 (magang kampus merdeka, 3 orang dari prodi TME atas nama Ahmad Hidayad, Budi Marli, dan Umar Sihab yang magang diluar kurikulum di Magang di PT. PANP, 1 orang dari prodi TMM atas nama Fitria dalam kegiatan pertukaran Pelajar antar provinsi dan 1 orang dari prodi TMP atas nama Rendy Maulana Program Markija Berdaya. sedangkan untuk mahasiswa yang meraih prestasi minimal tingkat nasional untuk di TW 1 berhasil dicapai oleh 1 orang mahasiswa prodi akuntansi atas nama Nur Aulia, yang berhasil menjadi pemenang dan berhak lolos dalam acara Pertukaran Pemuda Antar Negara utusan Provinsi Kalimantan Barat ke Negara Australia.', 'Adapun kendala yang dihadapi dalam mencapai IKK ini diantaranya: 1. Motivasi mahasiswa ke luar daerah atau kemauan mengikuti kegiatan luar kampus masih rendah sehingga partisipasi dalam pendaftaran program Kampus Merdeka masih rendah 2. Perbedaan persepsi dosen setiap prodi mengenai konversi nilai masih menjadi kendala sehingga langkah mengikutsertakan mahasiswa dalam MBKM masih tersendat. Ketegasan direktur sangat diharapkan dalam kondisi ini dengan menerbitkan perdir program MBKM (POLTESA belum memutuskan mengikuti program Kampus Merdeka). Hingga saat ini hanya segelintir dosen yang berbekal semangat untuk mendukung serta membimbing mahasiswa mengikuti program MBKM demi mendukung PK direktur 3. Awal tahun belum ada lomba yang digelar (belum dapat diikuti) serta Kendala pendanaan karena lokasi kompetisi rata-rata berada di luar Pulau Kalimantan dengan biaya pendaftaran yang cukup besar pula, Kendala waktu karena waktu persiapan seringkali mepet dan mahasiswa tidak bisa memenuhi standar minimal untuk dapat mengikuti kompetisi.', 'Adapun upaya tindak lanjut yang dilakukan dalam mengatasi kendala yang ada sesuai dengan apa yang dibahas dalam rapat pimpinan adalah : 1. Sosialisasi da pengarahan untuk memberikan motivasi kepada mahasiswa dengan kendali melalui dosen pembimbing akademik 2. Segera membuat panduan merdeka belajar serta menyemarakkan gema merdeka belajar yang disosialisasikan kepada dosen dan tendik agar menjadi habituasi baru di lingkungan kampus 3. aktif mendorong mahasiswa untuk meningkatkan kompetensi dan aktif berpartisipasi dalam berbagai kompetisi, menugaskan dosen pembimbing untuk meningkatkan kompetensi mahasiswa serta mengikuti kompetisi yang diadakan daring, serta mengalokasikan anggaran untuk lomba-lomba tingkat nasional maupun internasional.'),
(78, 1, 2, 1, 'IKU ini merupakan data capaian untuk lulusan yang mendapatkan pekerjaan dengan masa tunggu kurang dari 6 (enam) bulan dan gaji lebih dari 1,2 (satu koma dua) kali Upah Minimum Regional (UMR), lulusan yang melanjutkan studi di Perguruan Tinggi Negeri (PTN) Akademik Mendapatkan surat penerimaan untuk melanjutkan proses pembelajaran di program studi S2/S2 terapan, S3/S3 terapan di dalam negeri atau luar negeri dalam jangka waktu kurang dari 12 (dua belas) bulan. untuk capaian di TW 2 ini Poltesa berhasil mencapai 30,34% dari yang ditargetkan di TW 2 sebesar 33%. Dari total 379 orang lulusan dari 9 prodi yang di wisuda pada akhir tahun 2022 kemarin total ada sebanyak 115 orang yang masuk dalam kriteria IKU ini, dengan rincian ada sebanyak 95 orang yang telah berhasil mendapatkan pekerjaan, 1 orang yang melanjutkan studi, dan ada 19 orang yang menjadi wiraswasta. Adapun khusus di TW 2 ini hanya ada penambahan 32 orang lulusan yang berhasil mendapat pekerjaan seiring dengan perbaikan pada aplikasi tracer study dimana di tw 1 kemarin masih terdapat kendala untuk di TW 2 ini sudah kembali normal. Sedangkan untuk yang berwiraswasta dan melanjutkan studi tidak ada penambahan. Berikut nama nama alumni dan tempat ia bekerja: -Prodi AGB ada 3 orang yaitu Serin Oktavia (Balai Penyuluhan Pertanian), Levi Yanti (PNM) dan Norma Wati (PT Laik) -Prodi AIP ada 8 orang yaitu Sanertin, Diana, Jodi Pratama (PT. Unicoco Idustries Indonesia), Salindri (Djarum Retail Patnership Rama), Ami (Kantor Desa Tengguli), Susi Anisah (Badan Penyuluh Pertanian), Arifah Madani (PT. Aditama Yogyakarta), Ratih Cinliberty (SMK Negeri Semparuk sebagai Guru Produktif di bidang Olahan Pangan) -Prodi APK ada 1 orang yaitu Fajar Muslim (PT. Hutan Ketapang Industri) -Prodi MBP ada 4 orang yaitu Salendri (PT. Sumber Alfaria Trijaya, Tbk), Nurhasanah (PT. Saloinyan), NIKUen (Kantor Desa Temajuk), Nur Azira (Kantor Pegadaian) -Prodi TME ada 2 orang yaitu Dede Nur Iksan (PT. Bringin Inti Teknologi bit.corp), Widi Ariski (PT. Karya Boga Mitra KBM Sambas) -Prodi TMP ada 1 orang atas nama Ricki (PT Nindya Karya) -Prodi MIF ada 11 orang yaitu atas nama Mohammad Fazrul (Pondok Digital Aghnia), Ria (Smkn 1 selakau timur), Nunung Lestari (Badan Pusat Statistik), Sahid Sadiqi (PT Borneo Lancar Abadi), Shinta Nabila ( Sdn 02 galing), Ira Pratiwi (RSU Harapan Bersama), Tia Astuti (Nashpetshop), NUNUNG LESTARI (Badan Pusat Statistik), Dewi purwasih dan Yudi (PT Sumber Alfaria Trijaya Tbk/ Alfamart) -Prodi AKP ada 6 orang yaitu atas nama Andrianto (Dinas Koperasi, Usaha Kecil, Menengah, Perindustrian dan Perdagangan Kab Sambas) Deli (BAKEUDA Sambas), Annen (PT. Sambas Alam Lestari), Selpiani (Pendata Lapangan Regsosek BPS Sambas), Nely (PT. Sambas Alam Lestari) dan Dea Andini (CV. Ayracard Barokah). Adapun upaya yang telah dilakukan dalam mencapai IKU ini diantaranya: 1. Melakukan Pembekalan kepada wisudawan dan calon wisudawan terkait pentingnya memberikan data di aplikasi tracer study 2. Terus mengaktifkan grub WA alumni 3. Meningkatkan pengelolaan aplikasi tracer study.', 'Kendala yang dialami dalam melakukan pengukuran pada IKU ini diantaranya: 1. Untuk beberapa prodi lowongan cukup terbuka lebar karena banyak perusahaan yang memerlukan tenaga kerja bidang perawatan perbaikan, hanya saja beberapa perusahaan memerlukan pekerja yang telah memiliki pengalaman kerja 2. Masih banyak alumni yang belum mengambil ijazah dan mengisi data di tracer study 3. Adanya alumni yang lost contak atau berganti nomor.', 'Adapun tindak lanjut yang dilakukan dalam mengatasi kendala-kendala tersebut sesuai dengan arahan pimpinan pada saat rapat pengukuran kinerja diantaranya: 1. Meningkatkan kemampuan mahasiswa semasa kuliah seperti mendapatkan pengalaman dan sertifikat magang, serta dalam ilmu kewirausahaan. Agar ketika lulus kuliah tidak perlu mencari pekerjaan, namun justru dapat mencipatakan lapangan pekerjaan baru dengan berwirausaha 2. Melalui WA grub alumni, para kaprodi diminta untuk menghimbau alumni untuk segera melakukan pengambilan ijazah dan meminta melakukan update jika ada perubahan nomor Hp dan status pekerjaan atau usaha 3. melakukan perisapan pembekalan untuk calon wisudawan yang akan di wisuda bulan agustus di tahun ini'),
(79, 2, 2, 1, 'IKU ini merupakan data capaian untuk Mahasiswa yang mendapatkan paling sedikit 20 (dua puluh) sks dari kegiatan di luar kampus (dengan dosen pembimbing), sesuai dengan Buku Panduan Merdeka Belajar serta Berprestasi dalam kompetisi atau lomba paling rendah tingkat nasional. Adapun cara perhitungannya adalah jumlah mahasiswa yang Mahasiswa yang mendapatkan paling sedikit 20 (dua puluh) sks dari kegiatan di luar dan Berprestasi dalam kompetisi atau lomba paling rendah tingkat nasional dibagi dengan jumlah mahasiswa aktif ditahun 2023 di kali 100%. untuk capaian di TW 2 ini Poltesa berhasil mencapai 0,96 % dari yang ditargetkan sebesar 3,75%. untuk saat ini berdasarkan data pada PDDIKTI ada sekitar 1.980 mahasiswa aktif yang ada di lingkungan Poltesa. dari 1.980 mahasiswa aktif tersebut total sampai dengan TW 2 ini ada sebanyak 13 orang mahasiswa yang telah menghabiskan paling sedikit 20 sks diluar kampus bertambah 5 orang dari capaian di TW 1 yaitu 4 orang dari Prodi MBP atas nama Marhapida Rabbani (IISMA 2023), Rian Adi Wijatmiko (IISMA 2023), Nur Zaki dan Didik Dwi Wahyudi (Pertukaran Mahasiswa Merdeka Polibatam) dan ada 1 orang dari prodi AKP yaitu atas nama Rinda Nur Atika (Kampus Mengajar Kemdikbud tahun 2022 penempatan di SMP Muhammadiyah 3 Pontianak). sedangkan untuk mahasiswa yang meraih prestasi minimal tingkat nasional sampai dengan di TW 2 berhasil dicapai oleh 10 orang mahasiswa. Khusus di TW 2 ada penambahan sebanyak 5 orang yaitu dari prodi AGB 1 orang yaitu atas nama Adrianto (Juara 3 Tilawah Putra pada MTQ Politeknik Tingkat Nasional Tahun 2023/1444 H), dari prodi AIP 1 orang yaitu atas nama Era Sagita (lolos seleksi ProgramPertukaran Pemuda Antar Provinsi 2023), dari prodi MBP ada 1 orang yaitu atas nama Nur Izatul Egiantri (Finalis Putri Remaja Nusantara 2023), dari prodi TME ada 2 orang yaitu atas nama Abdul Rahman (Juara 2 Tartil Putra Kategori Qiraah Politeknik Pertanian Negeri Pangkajene Kepulauan), Alkadri (Putra Nusantara Photogenic 2023). Adapun upaya yang telah dilakukan dalam mendukung tercapainya IKU ini diantaranya: 1. dengan mengikutkan serta mendorong mahasiswa untuk mengikuti magang mereka 2. Selalu memonitoring kegiatan kompetisi Nasional yang dapat diikuti mahasiswa 3. Mahasiswa didoronng mengikuti kompetisi sesuai minat dan bakat masing-masing. Saat ini sudah dilakukan pemilihan mahasiswa yang akan mewakili Poltesa dalam ajang kompetisi pariwisata nasional.', 'Adapun kendala yang dihadapi dalam mencapai IKU ini diantaranya: 1. Masih belum banyak lomba yang digelar (belum dapat diikuti) serta Kendala pendanaan karena lokasi kompetisi rata-rata berada di luar Pulau Kalimantan dengan biaya pendaftaran yang cukup besar pula, Kendala waktu karena waktu persiapan seringkali mepet dan mahasiswa tidak bisa memenuhi standar minimal untuk dapat mengikuti kompetisi 2. Perbedaan persepsi dosen setiap prodi mengenai konversi nilai masih menjadi kendala sehingga langkah mengikutsertakan mahasiswa dalam MBKM masih tersendat. Ketegasan direktur sangat diharapkan dalam kondisi ini dengan menerbitkan perdir program MBKM (POLTESA belum memutuskan mengikuti program Kampus Merdeka). Hingga saat ini hanya segelintir dosen yang berbekal semangat untuk mendukung serta membimbing mahasiswa mengikuti program MBKM demi mendukung PK direktur 3. Motivasi mahasiswa ke luar daerah atau kemauan mengikuti kegiatan luar kampus masih rendah sehingga partisipasi dalam pendaftaran program Kampus Merdeka masih rendah', 'Adapun upaya tindak lanjut yang dilakukan dalam mengatasi kendala yang ada sesuai dengan apa yang dibahas dalam rapat pimpinan adalah: 1. aktif mendorong mahasiswa untuk meningkatkan kompetensi dan aktif berpartisipasi dalam berbagai kompetisi, menugaskan dosen pembimbing untuk meningkatkan kompetensi mahasiswa serta mengikuti kompetisi yang diadakan daring, serta mengalokasikan anggaran untuk lomba-lomba tingkat nasional maupun internasional 2. Segera membuat panduan merdeka belajar serta menyemarakkan gema merdeka belajar yang disosialisasikan kepada dosen dan tendik agar menjadi habituasi baru di lingkungan kampus 3. Sosialisasi dan pengarahan untuk memberikan motivasi kepada mahasiswa dengan kendali melalui dosen pembimbing akademik'),
(80, 3, 2, 1, 'IKU ini merupakan data capaian untuk dosen yang berkegiatan tridharma di kampus lain, di QS100 berdasarkan bidang ilmu (QS100 by subject), bekerja sebagai praktisi di dunia industri, atau membina mahasiswa yang berhasil meraih prestasi paling rendah tingkat nasional dalam 5 (lima) tahun terakhir. pada TW 2 Poltesa berhasi mencapai 36,47 % dari yang ditargetkan di TW 2 sebesar 38%, dimana dari total 85 orang dosen yang ada di Poltesa ada 2 orang dosen yang berkegiatan tridarma dikampus lain yaitu atas nama Muhammad Usman sebagai Dosen Part Time Sekolah Tinggi Ilmu Kesehatan Prima Indonesia dan Eliza Noviriani sebagai Editor dan Reviewer Exsternal Jurnal GLOW (Jurnal Pengabdian Kepada Masyarakat) STIE SULTAN AGUNG Sumatera Utara. untuk dosen yang bekerja sebagai praktisi di dunia industri ada 2 orang yaitu atas nama Fathushahib dan Heldi Hastriyandi sebagai TRAINER untuk Kegiatan Program Vocational School Graduate Academy (VSGA) skema Junior Network Administrator. sedangkan untuk dosen yang membina mahasiswa yang berhasil meraih prestasi paling rendah tingkat nasional dalam 5 tahun terakhir ada penambahan sebanyak 5 orang (yang diklaim hanya 4) dari capaian di TW 1, yaitu atas nama Uray Dian Novita yaitu membina Adrianto Juara 3 Tilawah Putra pada MTQ Politeknik Tingkat Nasional Tahun 2023/1444 H, dari prodi AIP 1 orang yaitu atas nama Andi maryam membina mahasiswa lolos seleksi Program Pertukaran Pemuda Antar Provinsi 2023, dari prodi MBP ada 1 orang yaitu atas nama Nur Asti Fatihah (tidak diklaim) yang berhasil membina Finalis Putri Remaja Nusantara 2023), dari prodi TME ada 2 orang yaitu atas nama Erwin yang berhasil membina mahasiswa Juara 2 Tartil Putra Kategori Qiraah Politeknik Pertanian Negeri Pangkajene Kepulauan, Leo Dedy Anjiu yang berhasil membina mahasiswa lolos Putra Nusantara Photogenic 2023) Adapun upaya yang telah dilakukan dalam mendukung IKU ini diantaranya: 1. Beberapa dosen yang sedang proses menunggu penugasan mengajar sebgai Tutor dan Pengampu Mata Kuliah di Universitas Terbuka 2. Para dosen terus mencari informasi terkait pendaftaran untuk berkegiatan (meneliti atau mengikuti kegiatan pendidikan di QS 100) 3. Meningkatkan alokasi anggaran untuk pemenuhan persiapan dan keikutsertaan dalam lomba lomba nasional dan internasional.', 'Adapun kendala yang dihadapi diantaranya: 1. Beban kerja dosen di homebase sudah banyak bahkan berlebih, sehingga berkegiatan di kampus lain tidak menjadi prioritas bagi dosen 2. Kurangnya persiapan ketika penyelenggaraan bersamaan dengan jadwal pengajaran dan beban administrasi lainnya di kampus 3. Kegiatan tridarma perguruan tinggi yang menjadi kewajiban dosen membuat jadwal dosen cukup padat sehingga kegiatan menjadi praktisi dengan periode kerja tertentu belum bisa terlaksana. Keterlibatan dosen di DUDI lebih banyak bersifat sementara atau sebagai narasumber saja 4. Kendala pendanaan karena lokasi kompetisi rata-rata berada di luar Pulau Kalimantan dengan biaya pendaftaran yang cukup besar pula, serta Kendala waktu karena waktu persiapan seringkali mepet dan mahasiswa tidak bisa memenuhi standar minimal untuk dapat mengikuti kompetisi.', 'Adapun tindak lanjut yang dilakukan berdasarkan rapat pimpinan adalah: 1. Menindaklanjuti PKS dan MoU dengan kampus lain dalam pelaksanaan tridarma terutama penelitian dan pengabdian kepada masyarakat 2. peningkatan kemampuan berbahasa Inggris bagi dosen, Pengaturan jadwal dosen untuk mendaftar short course atau kegiatan lain di QS 100 3. Memperluas dan memperkuat jejaring dengan DUDI bidang pariwisata dan hospitality agar menambah kesempatan dosen untuk berkegiatan sebagai praktisi 4. mengikuti kompetisi yang diadakan daring, persiapan intensif melalui bimbingan dosen serta menambah anggaran untuk mengikuti perlombaan.'),
(81, 5, 2, 1, 'IKU ini merupakan data capaian untuk dosen tetap yang berkualifikasi akademik S3, memiliki sertifikat kompetensi/profesi yang diakui oleh industri dan dunia kerja, atau berasal dari kalangan praktisi profesional, dunia industri, atau dunia kerja. Adapun cara perhitungannya adalah jumlah dosen yang berkualifikasi akademik S3, memiliki sertifikat kompetensi/profesi yang diakui oleh industri dan dunia kerja atau berasal dari kalangan praktisi profesional, dunia industri, atau dunia kerja dibagi dengan jumlah dosen tetap yang ada di Politeknik Negeri Sambas di kali 100%. untuk TW 2 Poltesa berhasil mencapai 64,71% dari yang ditargetkan di TW 2 sebesar 60%. Dari total 85 orang dosen tetap yang ada di Poltesa, di TW 2 ini ada 4 orang dosen yang mendapatkan sertifikasi, yaitu 2 orang dari prodi AIP atas nama andiyono dan andi maryam yang mendapat sertifikat kompetensi Audit halal. 2 orangnya lagi dari prodi AKP yaitu atas nama Eliza Noviriani dan Lailatul Mukaromah yang memperoleh sertifikat kompetensi Pendamping UMKM. sedangkan untuk dosen tetap berkualifikasi S3 hingga saat ini poltesa belum memiliki, namum untuk saat ini sudah ad lebih dari 4 orang dosen tetap yang melanjutkan pendidikan S3. Adapun upaya yang telah dilakukan dalam mendukung IKU ini diantaranya: 1. para dosen mengikuti pelatihan dan uji kompetensi yang sesuai bidang terlebih lagi yang diselenggarakan dan dibiayai oleh pusat 2. memantau perkembangan dosen dosen yang melanjutkan S 3 3. melakukan tindak lanjut MOU terkait ketersediaan tenaga ahli dari industri untuk bisa mengajar di Poltesa.', 'Dalam mencapai IKU ini ada beberapa kendala: 1. banyak dosen senior yang enggan melanjutkan S3 dikarenakan pembayaran serdos di hentikan 2. jumlah dosen yang terbatas sehingga jika banyak dosen yang melanjutkan studi secara bersamaan akan mengganggu proses belajar mengajar', 'Adapun tindak lanjut yang disampaikan pimpinan dalam rapat pengukuran ialah: 1. terus mendorong dan mempermudah izin bagi dosen yang ingin melanjutkan studi 2. menjaga ritme dan kuantitas dosen yang akan melanjutkan studi agar tidak terjadi kekosongan pengajar karena ditinggal lanjut studi.'),
(82, 6, 2, 1, 'IKU ini merupakan data capaian untuk Jumlah keluaran penelitian dan pengabdian kepada masyarakat yang berhasil mendapat rekognisi internasional atau diterapkan oleh masyarakat per jumlah dosen. Adapun cara perhitungannya adalah jumlah keluaran penelitian dan pengabdian kepada masyarakat yang berhasil mendapat rekognisi internasional atau diterapkan oleh masyarakat dibagi dengan jumlah dosen tetap yang ada di Politeknik Negeri Sambas. untuk di TW 2 Poltesa berhasi mencapai sebesar 0.15 hasil penelitian per jumlah dosen dari yang ditargetkan di TW 2 sebesar 0,1 hasil penelitian per jumlah dosen. Dari 85 orang dosen tetap yang ada di Poltesa, ada 13 orang yang masuk dalam kategori IKU ini, khusus di TW 2 ada penambahan sebanyak 6 orang, yaitu 3 orang dosen Prodi MBP atas nama Delyanet, Tita Rosalina, Rossi Evita yang berhasil menerbitkan HAKI Penulisan Book Chapter/ Bab dalam Buku. 1 orang prodi AIP atas nama Rozana yang berhasil menerbitkan Buku dengan judul Accelerating Sustainable Innovation Towards Society 5.0. 1 orang dosen dari prodi TME atas nama Daud Perdana dan 1 orang dari prodi TMP atas nama Suhendra yang Menghasilkan buku ber-ISBN dengan judul Tradisi Ngopi, Minuman Kopi dan Warung Kopi. untuk capaian IKU ini diharapkan masih akan terus bertambah sejalan dengan penyeleksian proposal Penelitian dan PKM Dosen dilingkungan Poltesa.', 'Adapun kendala yang dihadapi diantaranya: 1. daya saing, kemampuan bahasa Inggris, dan biaya seringkali menjadi kendala partisipasi dalam konferensi internasional 2. hasil penelitian dan pengabdian dosen masih banyak yang belum diterapkan langsung dimasyarakat', 'Adapun tindak lanjut yang dilakukan berdasarkan hasil rapat pimpinan diantaranya: 1. memfasilitasi dosen dalam meningkatkan kemampuan berbahasa inggris dengan bantuan dan kerjasama dari UPT TIK, serta memberikan insentif dan bantuan untuk biaya jurnal dan konferensi internasional 2. mengoordinasikan penelitian dan pengabdian dosen agar lebih bermanfaat dan dapat diterapkan langsung dimasyarakat melalui seleksi proposal penelitian dan PKM yang dilakukan oleh P3M.'),
(83, 7, 2, 1, 'IKU ini merupakan data capaian untuk Jumlah program studi S1 dan D4/D3/D2 yang melaksanakan kerja sama dengan mitra dimana harus tertuang di MOU komitmen perusahaan atau mitra dalam pengrekrutan alumi. Adapun cara perhitungannya adalah jumlah program studi yang melaksanakan kerjasama dengan mitra dibagi dengan jumlah program studi yang ada di Politeknik Negeri Sambas di kali 100%. untuk capaian IKU 3.1 di TW 2 ini berhasil dicapai sebesar 55,56% dari target sebesar 44,44%. untuk kegiatan yang sudah dilakukan diantaranya adalah terkait tempat magang industri, pengembangan kurikulum, serapan lulusan serta bantuan dosen yang berasal dari praktisi / industri. secara umum 9 prodi yang ada sudah melaksanakan kerjasama dengan mitra, namun untuk penambahan kerja sama baru atau pembaharuan kerja sama yang sudah ada di TW 2 ini ada dilaksakan oleh 5 prodi (hanya diklaim 1) dari 9 prodi yang ada yaitu prodi AIP (tidak diklaim) dengan 2 MOU yaitu dengan PT. Khatulistiwa Global Berkah dan PT. Pakunam Tirtajaya Perkasa Maskua Singkawang. Prodi MBP (tidak diklaim) MOU dengan Wahana Bahari Paloh dan Perhimpunan Hotel dan Restoran Indonesis (PHRI) Pengurus Provinsi Kalimantan Barat. Prodi APK (tidak diklaim) MOU dengan CV. Farm 169. Prodi TMP (tidak diklaim) dan Prodi TME MOU dengan PT. Anugerah Rezeki Teknindo.', 'Adapun kendala utama yang dihadapi dalam mendukung IKU ini adalah: 1. masih sulitnya membangun Komitmen dengan mitra terutama dalam penyerapan tenaga kerja dari alumni 2. Pihak industri membuka rekrutmen dan memprioritaskan lulusan Poltesa untuk lulus dalam proses rekrutmen namun tidak banyak mahasiswa yang berminat dengan posisi yang ditawarkan perusahaan tidak ada bukti tertulis atau formal terkait permintaan tersebut.', 'adapun solusi yang diusahakan saat ini adalah: 1. melakukan Peningkatan Kompetensi Dosen dan Mahasiswa melalui sertifikasi kompetens berlisensi yang diakui pemerintah serta terus mengoptimalkan kegiatan kerjasama dengan mitra agar bisa langsung merekrut lulusan. 2. membagikan info rekrutmen dari mitra kepada alumni, melakukan career coaching, mendorong alumni untuk mendaftar kerja secara bertanggung jawab 3. mengadakan career expo (walk-in interview) di kampus.'),
(84, 8, 2, 1, 'IKU ini merupakan data capaian untuk jumlah mata kuliah S1 dan D4/D3/D2 yang menggunakan metode pembelajaran pemecahan kasus (case method) atau pembelajaran kelompok berbasis projek (team-based project) sebagai sebagian bobot evaluasi. Adapun cara perhitungannya adalah jumlah mata kuliah S1 dan D4/D3/D2 yang menggunakan metode pembelajaran pemecahan kasus (case method) atau pembelajaran kelompok berbasis projek (team-based project) sebagai sebagian bobot evaluasi dibagi dengan jumlah mata kuliah yang ada di Politeknik Negeri Sambas di kali 100%. untuk IKU di TW 2 Poltesa mencapai 24,04% dari target sebesar 21%. dimana dari total 391 mata kuliah yang ada di 9 prodi, ada 94 mata kuliah yang masuk dalam kategori IKU ini. di semester genap yang sedang berlangsung ini ada 48 mata kuliah yang menggunakan metode pembelajaran pemecahan kasus (case method) bertambah sebanyak 23 mata kuliah dari TW 1 yang terbagi di 4 prodi yaitu prodi TME 9 mata kuliah (Praktik Kerja Bangku dan Plat, Gambar Teknik, Praktik Kerja Las, Aplikasi dan Pemograman Komputer, Praktik Mesin Perkakas, Pneumatik dan Hidrolik, Praktik Perawatan Dasar, Teknik Listrik Terapan, dan Praktik Teknik Mesin Konversi Energi), lalu prodi TMP ada 10 mata kuliah (Praktik Kerja Bangku dan Plat, Praktik Kerja Las, CAD 3 dimensi, Pengujian Bahan dan Metalurgi, Rekayasa Permesinan 1, Komputasi Teknik, Pneumatik dan Hidrolik, Praktik Teknik Perawatan, Gambar Mesin, dan Matematika Rekayasa), prodi TMM ada 4 mata kuliah (Produksi Amimasi 3D, Produksi Animasi 2D, Project Enterprise, 3D Environment Modelling). Sedangkan untuk mata kuliah yang menggunakan metode pembelajaran kelompok berbasis projek (team-based project) sebagai sebagian bobot evaluasi ada 46 mata kuliah (bertambah 13 Mata kuliah di TW 2) yang tersebar di 3 prodi yaitu prodi TME 3 mata kuliah (Praktik Perawatan Mesin Perkakas, Praktik Refrigerasi, dan Kewirausahaan), Prodi TMP 6 mata kuliah (Mesin Konversi Energi, Teknik Listrik dan Elektronika, Teknik Pengukuran dan Pengaturan I, Rekayasa Permesinan II, Teknik Pendingin, Teknik Pengukuran dan Pengaturan II), dan prodi MIF 4 mata kuliah (Dasar Pemrograman Web, Manajemen Proyek Sistem Informasi, Analisa dan Perancangan sistem Informasi, Pemrograman Berbasis Oriented). Adapun prores perkuliahan saat ini masih berlangsung di semester genap, dan mata kuliah yang termasuk dalam IKU ini juga akan terus bertambah sejalan dengan proses perkuliahan baik dalam bentuk praktikum maupun PBL.', 'adapun kendala dalam IKU ini adalah masih terbatasnya sarana dan prasarana untuk praktikum dan pembelajaran serta masih perlunya penyesuaian beberapa kurikulum prodi agar selalu selaras dengan kebutuhan industri.', 'pimpinan telah berkomitmen untuk terus meningkatkan sarana dan prasarana pendukung pembelajaran agar kegiatan pembelajaran yang ada dipoltesa dapat terus berkembang dan berjalan dengan lancar. Hal ini telah dilakukan dengan komitmen untuk seluruh prodi setiap tahunnya di berikan anggaran khusus untuk menambah dan meningkatkan alat alat praktikum mereka.'),
(85, 9, 2, 1, 'IKU ini merupakan data capaian untuk jumlah program studi S1 dan D4/D3/D2 yang memiliki akreditasi atau sertifikat internasional yang diakui pemerintah. Adapun cara perhitungannya adalah jumlah program studi S1 dan D4/D3/D2 yang memiliki akreditasi atau sertifikat internasional yang diakui pemerintah dibagi dengan jumlah program studi yang ada di Politeknik Negeri Sambas di kali 100%. untuk IKu Persentase program studi S1 dan D4/D3/D2 yang memiliki akreditasi yang diakui pemerintah atau sertifikat internasional yang diakui pemerintah di TW 2 ini capaian Poltesa masih 0% dari yang ditargetkan 0%. Untuk kondisi sekarang 9 prodi di Poltesa baru terakreditasi nasional dari BAN PT dengan status 5 prodi B dan sisa nya masih C. untuk saat ini prodi masih melakukan identifikasi dan Pemenuhan standar dan persyaratan Prodi akreditasi/sertifikasi yang diakui dan ada beberapa prodi yang lagi persiapan untuk reakreditasi. Selain itu juga bagian mutu terus belajar dan mengikuti kegiatan yang berkaitan dengan standar-standar akreditasi ataupun sertifikat internasional yang diakui oleh pemerintah serta melaksanakan beberapa pelatihan untuk teknisi dan dosen dengan pelatihan yang berstandar ISO.', 'Belum terpenuhinya persyaratan untuk mendapatkan akreditasi atau sertifikasi internasonal yang diakui pemerintah.', 'Pimpinan terus memacu dan memotivasi prodi untuk memenuhi standar/persyaratan akreditasi/sertifikasi serta memberikan dukungan anggaran untuk kegiatan seminar dan pelatihan untuk prodi agar bisa mencapai IKU ini.'),
(86, 1, 3, 1, 'IKU ini merupakan data capaian untuk lulusan yang mendapatkan pekerjaan dengan masa tunggu kurang dari 6 (enam) bulan dan gaji lebih dari 1,2 (satu koma dua) kali Upah Minimum Regional (UMR), lulusan yang melanjutkan studi di Perguruan Tinggi Negeri (PTN) Akademik Mendapatkan surat penerimaan untuk melanjutkan proses pembelajaran di program studi S2/S2 terapan, S3/S3 terapan di dalam negeri atau luar negeri dalam jangka waktu kurang dari 12 (dua belas) bulan. untuk capaian di TW 3 ini Poltesa berhasil mencapai 38,26% dari yang ditargetkan di TW 3 sebesar 48%. Dari total 379 orang lulusan dari 9 prodi yang di wisuda pada akhir tahun 2022 kemarin total ada sebanyak 145 orang yang masuk dalam kriteria IKU ini, dengan rincian ada sebanyak 121 orang yang telah berhasil mendapatkan pekerjaan, 2 orang yang melanjutkan studi, dan ada 22 orang yang menjadi wiraswasta. Adapun khusus di TW 3 ini hanya ada penambahan 26 orang lulusan yang berhasil mendapat pekerjaan seiring dengan perbaikan pada aplikasi tracer study dimana di tw 1 dan tw 2 kemarin. Sedangkan untuk yang berwiraswasta ada penambahan 3 orang dan melanjutkan studi ada penambahan 1 orang. Adapun upaya yang telah dilakukan dalam mencapai IKU ini diantaranya: 1. Melakukan sharing dan diskusi dengan satker lain terkait stragegi yang dilakukan dalam peningkatan capaian pengisian tracer study 2. Terus mengaktifkan grub WA alumni 3. Meningkatkan pengelolaan aplikasi tracer study.', 'Kendala yang dialami dalam melakukan pengukuran pada IKU ini diantaranya: 1. Untuk beberapa prodi lowongan cukup terbuka lebar karena banyak perusahaan yang memerlukan tenaga kerja bidang perawatan perbaikan, hanya saja beberapa perusahaan memerlukan pekerja yang telah memiliki pengalaman kerja 2. Masih banyak alumni yang belum mengambil ijazah serta mengisi dan mengupdate data di tracer study 3. Adanya alumni yang lost contact atau berganti nomor.', 'Adapun tindak lanjut yang dilakukan dalam mengatasi kendala-kendala tersebut sesuai dengan arahan pimpinan pada saat rapat pengukuran kinerja diantaranya: 1. Meningkatkan kemampuan mahasiswa semasa kuliah seperti mendapatkan pengalaman dan sertifikat magang, serta dalam ilmu kewirausahaan. Agar ketika lulus kuliah tidak perlu mencari pekerjaan, namun justru dapat mencipatakan lapangan pekerjaan baru dengan berwirausaha 2. Melalui WA grub alumni, para kaprodi diminta untuk menghimbau alumni untuk segera melakukan pengambilan ijazah dan meminta melakukan update jika ada perubahan nomor Hp dan status pekerjaan atau usaha 3. Akan mencoba memaksimalkan ikatan alumni dan kontak alumni yang aktif, yang nantinya akan dilakukan pendataan secara langsung dengan cara dihubungi satu persatu oleh staff akademik dan staff prodi'),
(87, 2, 3, 1, 'IKU ini merupakan data capaian untuk Mahasiswa yang mendapatkan paling sedikit 20 (dua puluh) sks dari kegiatan di luar kampus (dengan dosen pembimbing), sesuai dengan Buku Panduan Merdeka Belajar serta Berprestasi dalam kompetisi atau lomba paling rendah tingkat nasional. Adapun cara perhitungannya adalah jumlah mahasiswa yang Mahasiswa yang mendapatkan paling sedikit 20 (dua puluh) sks dari kegiatan di luar dan Berprestasi dalam kompetisi atau lomba paling rendah tingkat nasional dibagi dengan jumlah mahasiswa aktif ditahun 2023 di kali 100%. untuk capaian di TW 3 ini Poltesa berhasil mencapai 3,03% dari yang ditargetkan sebesar 5,75%. untuk saat ini berdasarkan data pada PDDIKTI ada sekitar 1.980 mahasiswa aktif yang ada di lingkungan Poltesa. dari 1.980 mahasiswa aktif tersebut total sampai dengan TW 3 ini ada sebanyak 47 orang mahasiswa yang telah menghabiskan paling sedikit 20 sks diluar kampus bertambah 34 orang dari capaian di TW 2, yaitu 20 orang dari Prodi AIP, ada 2 orang dari prodi AGB, 3 orang dari prodi MBP, 2 orang dari prodi MIF, 3 orang dari Prodi TMM dan 4 orang dari prodi AKP 3 orang. sedangkan untuk mahasiswa yang meraih prestasi minimal tingkat nasional sampai dengan di TW 3 berhasil dicapai oleh 13 orang mahasiswa. Khusus di TW 3 ada penambahan sebanyak 7 orang yaitu dari prodi AIP 1 orang, dan dari prodi AKP ada 6 orang. Adapun untuk data mahasiswa yang meraih prestasi adalah sebagai berikut : Nur Aulia Perserta Pertukaran Pemuda Antar Negara (PPAN) utusan Provinsi Kalimantan Barat ke Australia tahun 2023 Zarina Juara 1 Kategori Teresponsif Lomba Poster Olimpiade Akuntansi Vokasi (OAV) 6 Nasional 2023 Dhiemas Permana Juanda Juara 1 Kategori Teresponsif Lomba Poster Olimpiade Akuntansi Vokasi (OAV) 6 Nasional 2023 dan Juara 2 Kategori Terdramatis Lomba Konten Video Olimpiade Akuntansi Vokasi (OAV) 6 Nasional 2023 Anwar Juara 3 Kategori Tersolutif Konten Video Olimpiade Akuntansi Vokasi (OAV) 6 Nasional 2023 dan Aldo Juara 3 Kategori Tersolutif Konten Video Olimpiade Akuntansi Vokasi (OAV) 6 Nasional 2023. Untuk saat ini Mahasiswa masih mengikuti program MBKM 2023 hingga semester ganjil ini berakhir. Beberapa progrm flagship MBKM sudah mulai dibuka. Adapun upaya yang telah dilakukan dalam mendukung tercapainya IKU ini diantaranya: 1. dengan mengikutkan serta mendorong mahasiswa untuk mengikuti magang mereka 2. Selalu memonitoring kegiatan kompetisi Nasional yang dapat diikuti mahasiswa 3. Mahasiswa didorong mengikuti kompetisi sesuai minat dan bakat masing-masing. Saat ini sudah dilakukan pemilihan mahasiswa yang akan mewakili Poltesa dalam ajang kompetisi nasional yang tersisa', 'Adapun kendala yang dihadapi dalam mencapai IKU ini diantaranya: 1. Masih belum banyak lomba yang digelar (belum dapat diikuti) serta Kendala pendanaan karena lokasi kompetisi rata-rata berada di luar Pulau Kalimantan dengan biaya pendaftaran yang cukup besar pula, Kendala waktu karena waktu persiapan seringkali mepet dan mahasiswa tidak bisa memenuhi standar minimal untuk dapat mengikuti kompetisi 2. Perbedaan persepsi dosen setiap prodi mengenai konversi nilai masih menjadi kendala sehingga langkah mengikutsertakan mahasiswa dalam MBKM masih tersendat. Ketegasan direktur sangat diharapkan dalam kondisi ini dengan menerbitkan Perdir program MBKM (POLTESA belum memutuskan mengikuti program Kampus Merdeka). Hingga saat ini hanya segelintir dosen yang berbekal semangat untuk mendukung serta membimbing mahasiswa mengikuti program MBKM demi mendukung PK direktur 3. Motivasi mahasiswa ke luar daerah atau kemauan mengikuti kegiatan luar kampus masih rendah sehingga partisipasi dalam pendaftaran program Kampus Merdeka masih rendah', 'Adapun upaya tindak lanjut yang dilakukan dalam mengatasi kendala yang ada sesuai dengan apa yang dibahas dalam rapat pimpinan adalah: 1. aktif mendorong mahasiswa untuk meningkatkan kompetensi dan aktif berpartisipasi dalam berbagai kompetisi, menugaskan dosen pembimbing untuk meningkatkan kompetensi mahasiswa serta mengikuti kompetisi yang diadakan daring, serta mengalokasikan anggaran untuk lomba-lomba tingkat nasional maupun internasional 2. Segera membuat panduan merdeka belajar serta menyemarakkan gema merdeka belajar yang disosialisasikan kepada dosen dan tendik agar menjadi habituasi baru di lingkungan kampus 3. Sosialisasi dan pengarahan untuk memberikan motivasi kepada mahasiswa dengan kendali melalui dosen pembimbing akademik'),
(88, 3, 3, 1, 'IKU ini merupakan data capaian untuk dosen yang berkegiatan tridharma di kampus lain, di QS100 berdasarkan bidang ilmu (QS100 by subject), bekerja sebagai praktisi di dunia industri, atau membina mahasiswa yang berhasil meraih prestasi paling rendah tingkat nasional dalam 5 (lima) tahun terakhir. pada TW 3 Poltesa berhasi mencapai 41,17 % dari yang ditargetkan di TW 3 sebesar 49%, dimana dari total 85 orang dosen yang ada di Poltesa ada 3 orang dosen yang berkegiatan tridarma dikampus lain, bertambah 1 orang dari capaian sampai dengan TW 2 yaitu atas nama Pande Putu Santoso sebagai Tutor pada Pokjar Abdurachman-Senujuh Kab. Sambas, Universitas Terbuka. untuk dosen yang bekerja sebagai praktisi di dunia industri ada 2 orang yaitu atas nama Iman Syahrizal sebagai pengajar dalam kegiatan bimbingan teknis WUB IKM bengkel las di Kabupaten Sambas dan Ari Rianto, ST, MT sebagai sebagai pengajar dalam kegiatan bimbingan teknis WUB IKM bengkel las di Kabupaten Singkawang. sedangkan untuk dosen yang membina mahasiswa yang berhasil meraih prestasi paling rendah tingkat nasional dalam 5 tahun terakhir tidak ada penambahan dari capaian TW sebelumnya. Adapun upaya yang telah dilakukan dalam mendukung IKU ini diantaranya: 1. Beberapa dosen yang sedang proses menunggu penugasan mengajar sebgai Tutor dan Pengampu Mata Kuliah di Universitas Terbuka 2. Para dosen terus mencari informasi terkait pendaftaran untuk berkegiatan (meneliti atau mengikuti kegiatan pendidikan di QS 100) 3. Meningkatkan alokasi anggaran untuk pemenuhan persiapan dan keikutsertaan dalam lomba lomba nasional dan internasional.', 'Adapun kendala yang dihadapi diantaranya: 1. Beban kerja dosen di homebase sudah banyak bahkan berlebih, sehingga berkegiatan di kampus lain tidak menjadi prioritas bagi dosen 2. Kurangnya persiapan ketika penyelenggaraan bersamaan dengan jadwal pengajaran dan beban administrasi lainnya di kampus 3. Kegiatan tridarma perguruan tinggi yang menjadi kewajiban dosen membuat jadwal dosen cukup padat sehingga kegiatan menjadi praktisi dengan periode kerja tertentu belum bisa terlaksana. Keterlibatan dosen di DUDI lebih banyak bersifat sementara atau sebagai narasumber saja 4. Kendala pendanaan karena lokasi kompetisi rata-rata berada di luar Pulau Kalimantan dengan biaya pendaftaran yang cukup besar pula, serta Kendala waktu karena waktu persiapan seringkali mepet dan mahasiswa tidak bisa memenuhi standar minimal untuk dapat mengikuti kompetisi.', 'Adapun tindak lanjut yang dilakukan berdasarkan rapat pimpinan adalah: 1. Menindaklanjuti PKS dan MoU dengan kampus lain dalam pelaksanaan tridarma terutama penelitian dan pengabdian kepada masyarakat 2. peningkatan kemampuan berbahasa Inggris bagi dosen, Pengaturan jadwal dosen untuk mendaftar short course atau kegiatan lain di QS 100 3. Memperluas dan memperkuat jejaring dengan DUDI bidang pariwisata dan hospitality agar menambah kesempatan dosen untuk berkegiatan sebagai praktisi 4. mengikuti kompetisi yang diadakan daring, persiapan intensif melalui bimbingan dosen serta menambah anggaran untuk mengikuti perlombaan.'),
(89, 5, 3, 1, 'IKU ini merupakan data capaian untuk dosen tetap yang berkualifikasi akademik S3, memiliki sertifikat kompetensi/profesi yang diakui oleh industri dan dunia kerja, atau berasal dari kalangan praktisi profesional, dunia industri, atau dunia kerja. Adapun cara perhitungannya adalah jumlah dosen yang berkualifikasi akademik S3, memiliki sertifikat kompetensi/profesi yang diakui oleh industri dan dunia kerja atau berasal dari kalangan praktisi profesional, dunia industri, atau dunia kerja dibagi dengan jumlah dosen tetap yang ada di Politeknik Negeri Sambas di kali 100%. untuk TW 3 Poltesa berhasil mencapai 68,24% dari yang ditargetkan di TW 3 sebesar 63%. Dari total 85 orang dosen tetap yang ada di Poltesa, di TW 3 ini ada 3 orang dosen yang mendapatkan sertifikasi, yaitu 2 orang dari prodi TMM atas nama Vanie Wijaya dan U. Heri Mulyanto yang mendapat sertifikat kompetensi Digital Marketing. 1 orangnya lagi dari prodi AGB yaitu atas nama Ketty Andrayani yang memperoleh Sertifikasi Kompetensi PEKERTI. sedangkan untuk dosen tetap berkualifikasi S3 hingga saat ini poltesa belum memiliki, namum untuk saat ini sudah ad lebih dari 4 orang dosen tetap yang melanjutkan pendidikan S3. Adapun upaya yang telah dilakukan dalam mendukung IKU ini diantaranya: 1. para dosen mengikuti pelatihan dan uji kompetensi yang sesuai bidang terlebih lagi yang diselenggarakan dan dibiayai oleh pusat 2. memantau perkembangan dosen dosen yang melanjutkan S 3 3. melakukan tindak lanjut MOU terkait ketersediaan tenaga ahli dari industri untuk bisa mengajar di Poltesa.', 'Dalam mencapai IKU ini ada beberapa kendala: 1. banyak dosen senior yang enggan melanjutkan S3 dikarenakan pembayaran serdos di hentikan 2. jumlah dosen yang terbatas sehingga jika banyak dosen yang melanjutkan studi secara bersamaan akan mengganggu proses belajar mengajar', 'Adapun tindak lanjut yang disampaikan pimpinan dalam rapat pengukuran ialah: 1. terus mendorong dan mempermudah izin bagi dosen yang ingin melanjutkan studi 2. menjaga ritme dan kuantitas dosen yang akan melanjutkan studi agar tidak terjadi kekosongan pengajar karena ditinggal lanjut studi.'),
(90, 6, 3, 1, 'IKU ini merupakan data capaian untuk Jumlah keluaran penelitian dan pengabdian kepada masyarakat yang berhasil mendapat rekognisi internasional atau diterapkan oleh masyarakat per jumlah dosen. Adapun cara perhitungannya adalah jumlah keluaran penelitian dan pengabdian kepada masyarakat yang berhasil mendapat rekognisi internasional atau diterapkan oleh masyarakat dibagi dengan jumlah dosen tetap yang ada di Politeknik Negeri Sambas. untuk di TW 3 Poltesa berhasi mencapai sebesar 0.23 hasil penelitian per jumlah dosen dari yang ditargetkan di TW 3 sebesar 0,11 hasil penelitian per jumlah dosen. Dari 85 orang dosen tetap yang ada di Poltesa, ada 27 orang yang masuk dalam kategori IKU ini, khusus di TW 3 ada penambahan sebanyak 7 orang, yaitu 1 orang prodi TMM atas nama Narti Prihartini yang mengikuti 10th International Conference On ICT For Smart Society ( ICISS ) 2023 September 6-7, 2023, 3 orang dosen dari prodi TME atas nama Leo Dedy Anjiu, Ari Rianto, dan Ellys Mei Sundari, eo Dedy Anjiu, dan Ari Rianto menghasilkan publikasi pada jurnal TURBO Sinta 3 dengan judul Analisis panjang bidang kontak perontokan lada pada mesin perontok lada tipe silinder berjaring, Ellys Mei Sundari menghasilkan publikasi pada jurnal penelitian berjudul Analisis Statis Design Prototype Chassis Tubular Space Frame Kendaraan Listrik Berjenis Buggy dan 3 orang dari prodi TMP atas nama Iman Syahrizal, Irma Fahrizal Butsi Ningsih, dan Winda Apriani dimana Iman Syahrizal berupa publikasi Jurnal penelitian berjudul Rancang bangun mesin pengering buah pinang tipe rotari dengan sumber panas api kompor berbahan bahar oli bekas, Irma Fahrizal Butsi Ningsih berupa publikasi Jurnal penelitian berjudul Pembuatan Alat Pengupas Nanas Sistem Press, dan Winda Apriani berupa publikasi jurnal berjudul Analisis Statis Design Prototype Chassis Tubular Space Frame Kendaraan Listrik Berjenis Buggy. untuk capaian IKU ini diharapkan masih akan terus bertambah sejalan dengan penyeleksian proposal Penelitian dan PKM Dosen dilingkungan Poltesa.', 'Adapun kendala yang dihadapi diantaranya: 1. daya saing, kemampuan bahasa Inggris, dan biaya seringkali menjadi kendala partisipasi dalam konferensi internasional 2. hasil penelitian dan pengabdian dosen masih banyak yang belum diterapkan langsung dimasyarakat', 'Adapun tindak lanjut yang dilakukan berdasarkan hasil rapat pimpinan diantaranya: 1. memfasilitasi dosen dalam meningkatkan kemampuan berbahasa inggris dengan bantuan dan kerjasama dari UPT TIK, serta memberikan insentif dan bantuan untuk biaya jurnal dan konferensi internasional 2. mengoordinasikan penelitian dan pengabdian dosen agar lebih bermanfaat dan dapat diterapkan langsung dimasyarakat melalui seleksi proposal penelitian dan PKM yang dilakukan oleh P3M.'),
(91, 7, 3, 1, 'iku ini merupakan data capaian untuk jumlah program studi s1 dan d4/d3/d2 yang melaksanakan kerja sama dengan mitra dimana harus tertuang di mou komitmen perusahaan atau mitra dalam pengrekrutan alumi. adapun cara perhitungannya adalah jumlah program studi yang melaksanakan kerjasama dengan mitra dibagi dengan jumlah program studi yang ada di politeknik negeri sambas di kali 100%. untuk capaian iku 3.1 di tw 3 ini berhasil dicapai sebesar 100% dari target sebesar 66,67%. untuk kegiatan yang sudah dilakukan diantaranya adalah terkait tempat magang industri, pengembangan kurikulum, serapan lulusan serta bantuan dosen yang berasal dari praktisi / industri. secara umum 9 prodi yang ada sudah melaksanakan kerjasama dengan mitra, namun untuk penambahan kerja sama baru atau pembaharuan kerja sama yang sudah ada di tw 3 ini berdasarkan data dari tim kerjasama ada 10 kerjasama, yaitu kelompok masyarakat wahana bahari paloh terkait pengembangan pendidikan vokasi bidang konservasi perikanan kelautan dan pariwisata, Politeknik Negeri Banyuwangi, Politeknik Negeri Indramayu, Politeknik Negeri Subang, Politeknik Negeri Cilacap, Politeknik Negeri Fakfak, Politeknik Negeri Nusa Utara, Politeknik Negeri Ketapang, Politeknik Negeri Bengkalis dan Politeknik Negeri Nunukan terkait pengembangan pendidikan vokasi bidang konservasi perikanan kelautan dan pariwisata, SMKN 1 JAWAI terkait peningkatan kompetensi sumber daya manusia dan pengembangan pendidika serta pengembangan dan kerjasama masyarakat terinstitusi, UNIVERSITAS TELKOM terkait pks kolaborasi implementasi aplikasi eazy akreditasi dan perjanjian lisensi penggunaan merek dan aplikasi eazy, KEMENKUMHAM KALIMANTAN barat terkait pengembangan potensi industri dan ekonomi kreatif masyarakat melalui pemberdayaan dan pemanfaatan kekayaan intelektual di kabupaten sambas, pt. nusa talenta indonesia terkait program \"nusa karier” dan PT. DOCK BINA VISTA terkait pengembangan pendidikan vokasi bidang industri perkapalan. Dari kesemua Kerjasama tersebut, sebagian besar melibatkan seluruh prodi yang ada di Politeknik Negeri Sambas.', 'Adapun kendala utama yang dihadapi dalam mendukung IKU ini adalah: 1. masih sulitnya membangun Komitmen dengan mitra terutama dalam penyerapan tenaga kerja dari alumni 2. Pihak industri membuka rekrutmen dan memprioritaskan lulusan Poltesa untuk lulus dalam proses rekrutmen namun tidak banyak mahasiswa yang berminat dengan posisi yang ditawarkan perusahaan tidak ada bukti tertulis atau formal terkait permintaan tersebut.', 'adapun solusi yang diusahakan saat ini adalah: 1. melakukan Peningkatan Kompetensi Dosen dan Mahasiswa melalui sertifikasi kompetens berlisensi yang diakui pemerintah serta terus mengoptimalkan kegiatan kerjasama dengan mitra agar bisa langsung merekrut lulusan. 2. membagikan info rekrutmen dari mitra kepada alumni, melakukan career coaching, mendorong alumni untuk mendaftar kerja secara bertanggung jawab');
INSERT INTO `keterangan` (`id_ket`, `id_iku`, `id_triwulan`, `id_prodi`, `progres`, `kendala`, `strategi`) VALUES
(92, 8, 3, 1, 'IKU ini merupakan data capaian untuk jumlah mata kuliah S1 dan D4/D3/D2 yang menggunakan metode pembelajaran pemecahan kasus (case method) atau pembelajaran kelompok berbasis projek (team-based project) sebagai sebagian bobot evaluasi. Adapun cara perhitungannya adalah jumlah mata kuliah S1 dan D4/D3/D2 yang menggunakan metode pembelajaran pemecahan kasus (case method) atau pembelajaran kelompok berbasis projek (team-based project) sebagai sebagian bobot evaluasi dibagi dengan jumlah mata kuliah yang ada di Politeknik Negeri Sambas di kali 100%. untuk IKU di TW 3 Poltesa mencapai 38,36% dari target sebesar 21%. dimana dari total 391 mata kuliah yang ada di 9 prodi, ada 150 mata kuliah yang masuk dalam kategori IKU ini. Penambahan signifikan ini dikarenakan masuknya tahun ajaran semester gajil yang sedang berlangsung. Untuk sampai saat ini ada 75 mata kuliah yang menggunakan metode pembelajaran pemecahan kasus (case method) bertambah sebanyak 27 mata kuliah dari TW sebelumnya yang terbagi di 7 prodi yaitu prodi AGB sebanyak 4 mata kuliah (Matematika, Ilmu Pertanian, Bahasa Indonesia dan Sarana Produksi Pertanian), Prodi AIP ada 3 mata kuliah (Sanitasi dan Pengendalian Limbah Agroindustri, Keamanan Pangan dan Metodologi Penulisan Ilmiah), Prodi APK ada 5 Mata Kuliah (Hama Dan Penyakit Ikan, Teknologi Pembuatan Dan Pemberian Pakan, Koperasi dan Mitra Bisnis Perikanan, Pemanfaatan Limbah Hasil Perikanan dan Pembangunan Masyarakat Perikanan), Prodi MBP ada 5 Mata Kuliah (Statistik, K3, Dasar Akomodasi dan Restoran, Manajemen Hospitality dan Manajemen Keuangan), Prodi AKP ada 4 Mata Kuliah (Akuntansi Dasar I, Pengauditan I, Komputer Akuntansi I, dan Akuntansi Keuangan Menengah I), Prodi MIF ada 2 Mata Kuliah (Manajemen Proyek Sistem Informasi Dan Pemrograman Berorientasi Objek), dan prodi TMM ada 4 Mata Kuliah (Produksi Amimasi 3D, Produksi Animasi 2D, Project Enterprise, dan 3D Environment Modelling). Sedangkan untuk mata kuliah yang menggunakan metode pembelajaran kelompok berbasis projek (team-based project) sebagai sebagian bobot evaluasi ada 74 mata kuliah (bertambah 29 Mata kuliah dari TW sebelumnya) yang tersebar di 9 prodi yaitu prodi AGB sebanyak 5 mata kuliah (Teknik Budidaya Tanaman Perkebunan Sawit, Manajemen Pemasaran, Manajemen Keuangan, Manajemen Sumber Daya manusia dan Manajemen Produksi dan Operasional), Prodi AIP ada 4 mata kuliah ( Rekayasa Proses, IMKM, Manajemen SDM, E-commerce), Prodi APK ada 5 Mata Kuliah (Budidaya Pakan Alami, Budidaya Ikan Hias, Teknologi Pengemasan Hasil, Budidaya Perairan Payau Dan Laut Dan Manajemen Konservasi), Prodi MBP ada 5 Mata Kuliah (Bahasa Inggris Profesional, Alternative Tourism, Kajian Wisata Budaya dan Sejarah, Manajemen Tour and Guding dan Bahasa Inggris III), Prodi AKP ada 3 Mata Kuliah (Akuntansi Keuangan Lanjutan, Statistik dan Analisis Lap Keuangan), Prodi MIF ada 2 Mata Kuliah (Manajemen Proyek Sistem Informasi Dan Pemrograman Berorientasi Objek), dan prodi TMM ada 5 Mata Kuliah (Produksi Amimasi 3D, Produksi Animasi 2D, Project Enterprise, dan Environment Modelling Kewirausahaan). Adapun prores perkuliahan saat ini masih berlangsung di semester ganjil, dan mata kuliah yang termasuk dalam IKU ini juga akan terus bertambah sejalan dengan proses perkuliahan baik dalam bentuk praktikum maupun PBL.', 'singkatnya waktu persiapan dan waktu berkoordinasi dengan mata kuliah lainnya maupun dengan PBL bersama prodi lainnya serta kendala dalam memperbaharui (updating) kasus - kasus menjadi tantantan tersendiri bagi dosen maupun mahasiswa.', 'Perencanaan dan pemetaan project di awal semester dengan goal atau target yang jelas, fokus, dan terukur serta koordinasi dengan industri dan mitra prodi untuk updating berbabgai real-life kasus yang perlu dicarikan solusinya dalam proses pembelajaran mahasiswa'),
(93, 9, 3, 1, 'IKU ini merupakan data capaian untuk jumlah program studi S1 dan D4/D3/D2 yang memiliki akreditasi atau sertifikat internasional yang diakui pemerintah. Adapun cara perhitungannya adalah jumlah program studi S1 dan D4/D3/D2 yang memiliki akreditasi atau sertifikat internasional yang diakui pemerintah dibagi dengan jumlah program studi yang ada di Politeknik Negeri Sambas di kali 100%. untuk IKu Persentase program studi S1 dan D4/D3/D2 yang memiliki akreditasi yang diakui pemerintah atau sertifikat internasional yang diakui pemerintah di TW 3 ini capaian Poltesa masih 0% dari yang ditargetkan 0%. Untuk kondisi sekarang 9 prodi di Poltesa baru terakreditasi nasional dari BAN PT dengan status 5 prodi B dan sisa nya masih C. untuk saat ini prodi masih melakukan identifikasi dan Pemenuhan standar dan persyaratan Prodi akreditasi/sertifikasi yang diakui dan ada beberapa prodi yang lagi persiapan untuk reakreditasi. Selain itu juga bagian mutu terus belajar dan mengikuti kegiatan yang berkaitan dengan standar-standar akreditasi ataupun sertifikat internasional yang diakui oleh pemerintah serta melaksanakan beberapa pelatihan untuk teknisi dan dosen dengan pelatihan yang berstandar ISO. Untuk saat ini berapa prodi sedang persiapan untuk reakreditasi, yang paling mendekati yaitu prodi TMM yang hanya tinggal menunggu waktu untuk di asesmen lapangan oleh tim LAM PT.', 'Belum terpenuhinya persyaratan untuk mendapatkan akreditasi atau sertifikasi internasonal yang diakui pemerintah.', 'Pimpinan terus memacu dan memotivasi prodi untuk memenuhi standar/persyaratan akreditasi/sertifikasi serta memberikan dukungan anggaran untuk kegiatan seminar dan pelatihan untuk prodi agar bisa mencapai IKU ini.'),
(94, 1, 5, 1, 'IKU ini merupakan data capaian untuk lulusan yang Memiliki pekerjaan dalam rentang waktu 12 (dua belas) bulan setelah lulus baik di perusahaan swasta, termasuk perusahaan nasional, perusahaan multinasional, perusahaan rintisan (startup company) Usaha Mikro, Kecil dan Menengah (UMKM), dan lain-lain organisasi nirlaba institusi/organisasi multilateral lembaga pemerintah atau Badan Usaha Milik Negara (BUMN)/Badan Usaha Milik Daerah (BUMD), lulusan Melanjutkan proses pembelajaran di program studi profesi, S1/D4 terapan, S2/S2 terapan, S3/S3 terapan di dalam negeri atau luar negeri dalam rentang waktu kurang dari 12 (dua belas) bulan setelah lulus, serta lulusan yang menjadi wirausaha baik sebagai sebagai pendiri (founder)atau pasangan pendiri (co-founder,l perusahaan atau pekerja lepas (freelancer). Untuk perhitungannya adalah jumlah lulusan yang memiliki pekerjaan, lulusan yang melanjutkan studi di Perguruan Tinggi dan lulusan menjadi wiraswasta dibagi dengan jumlah wisudawan. Dimana setiap kriterian tersebut akan dilakukan pembobotan sesuai dengan hitungan yang ada di Peraturan Direktur Jenderal Pendidikan Vokasi Nomor 62/D/M/2023 Tentang Pedoman Indikator Kinerja Utama Perguruan Tinggi Negeri Vokasi. Berdasarkan Kepmendikbudristek Nomor 210/M/2023 Tentang Indikator Kinerja Utama Perguruan Tinggi Negeri Vokasi Dan Lldikti bahwa dalam pengukuran TW 4 ini harus menggunakan data yang ditampilkan oleh Aplikasi Sidakin. Adapun lulusan Politeknik Negeri Sambas yang menjadi dasar perhitungan pengukuran TW 4 ini adalah lulusan tahun 2021 dengan jumlah lulusan sebanyak 348 orang dengan minimal responden sebanyak 60% dari jumlah lulusan. Untuk capaian IKU ini di TW 4 berdasarkan hasil dari aplikasi Sidakin, Politeknik Negeri Sambas berhasil mencapai skor 65,19% dari yang ditargetkan di TW 4 sebesar 60%. Dari total 348 orang lulusan dari 9 prodi yang di wisuda pada akhir tahun 2021 kemarin total ada sebanyak 253 orang yang masuk dalam kriteria dan pembobotan IKU ini, dengan rincian ada sebanyak 126 orang yang telah berhasil mendapatkan pekerjaan, 1 orang yang melanjutkan studi, dan ada 126 orang yang menjadi wiraswasta. Adapun upaya yang telah dilakukan dalam mendukung IKU ini diantaranya: 1. Melakukan bembekalan kepada calon wisudawan setiap angkatan terkait pentingnya pengisian dan update data alumni 2. Meningkatkan jumlah bantuan kewirausahaan mahasiswa 3. Melakukan ekspo produk kewirausaan mahasiswa 4. Meningkatkan jumlah kerja sama, khususnya dalam hal rekrutmen lulusan untuk bekerja 5. Melakukan rapat bersama tim Tracer dan seluruh prodi terkait perubahan pola pelaporan dan data alumni yang digunakan 6. Menghubungi para alumni untuk melakukan pengisian dan update data di aplikasi tracer.', 'Kendala yang dialami dalam melakukan pengukuran pada IKU ini diantaranya: 1. Seringnya terjadi gangguan pada aplikasi tracer 2. Masih terbatasnya pihak industri/lembaga yang berkomitmen dalam pengrekrutan alumni 3. Banyak wirausaha mahasiswa yang tidak dilanjutkan ketika sudah lulus 4. Adanya alumni yang lost contact atau berganti nomor.', 'Adapun tindak lanjut yang dilakukan dalam mengatasi kendala-kendala tersebut sesuai dengan arahan pimpinan pada saat rapat pengukuran kinerja diantaranya: 1. Terus berkoordinasi dengan tim pengembang aplikasi serta menginformasikan kepada para alumni terkait aplikasi tracer 2. Melalu tim kerjasama, pimpinan menekankan untuk meningkatkan kualitas dan kuantitas kerja sama dengan mitra, khususnya terkait informasi lowongan dan rekrutmen lulusan 3. Melakukan pembinaan dan pendampingan kewirausahaan mahasiswa sampai dengan pasca lulus 4. Melalui WA grub alumni, para staff prodi meminta melakukan update jika ada perubahan nomor Hp dan status pekerjaan atau usaha.'),
(95, 2, 5, 1, 'IKU ini merupakan data capaian untuk Mahasiswa yang menghabiskan sampai dengan 20 (dua puluh) sks per semester di luar program studi dengan batas minimal yang dapat dihitung adalah paling sedikit 10 (sepuluh) sks untuk mahasiswa S1/D4/D3 yang mana kegiatan-Kegiatannya bisa berupa magang atau praktik kerja, proyek di desa, mengajar di sekolah, pertukaran pelajar, penelitian atau riset, kegiatan wirausaha, studi atau proyek independen, proyek kemanusiaan, bela negara dimana kegiatannya boleh dikombinasikan dan dihitung kumulatif. Serta mahasiswa yang Berprestasi dalam kompetisi atau lomba pada peringkat juara I - III pada kompetisi Internasional, Nasional maupun provinsi, Memiliki karya yang digunakan dunia usaha, industri dan masyarakat atau Mendapatkan sertifikasi kompetensi internasional. Adapun cara perhitungannya adalah jumlah mahasiswa aktif yang menghabiskan sampai dengan 20 (dua puluh) sks per semester di luar program studi dan jumlah mahasiswa yang Berprestasi dalam kompetisi atau lomba dibagi dengan jumlah mahasiswa aktif. Dimana setiap kriterian tersebut akan dilakukan pembobotan sesuai dengan hitungan yang ada di Peraturan Direktur Jenderal Pendidikan Vokasi Nomor 62/D/M/2023 Tentang Pedoman Indikator Kinerja Utama Perguruan Tinggi Negeri Vokasi. Berdasarkan Kepmendikbudristek Nomor 210/M/2023 Tentang Indikator Kinerja Utama Perguruan Tinggi Negeri Vokasi Dan Lldikti bahwa dalam pengukuran TW 4 ini harus menggunakan data yang ditampilkan oleh Aplikasi Sidakin. Adapun data yang digunakan adalah data mahasiswa aktif yang ada di PDDIKTI untuk periode Genap 2021/2022 dan Ganjil 2022/2023 yaitu sebanyak 2.231 orang. untuk capaian di TW 4 ini Poltesa berhasil mencapai 24,57% dari yang ditargetkan sebesar 30%. Berdasarkan data pada PDDIKTI dari 2.331 mahasiswa aktif tersebut total sampai dengan TW 4 ini ada sebanyak 391 orang Mahasiswa Menjalankan Magang Wajib Diluar Prodi dan ada sebanyak 46 orang mahasiswa yang berhasil meraih prestasi baik di level Internasional, Nasional dan Regional. Sedangkan untuk mahasiswa yang mengikuti Kampus merdeka berdasarkan data yang ditampilkan sidakin adalah 0, padahal menurut data capaian dan inputan di aplikasi PDDIKTI ada sekitar 120 orang mahasiswa. Adapun upaya yang telah dilakukan dalam mendukung tercapainya IKU ini diantaranya: 1. Mengajukan pembukaan priode untuk pelaporan PDDIKTI 2. Melakukan pendataan ulang dan penginputan terkait kegiatan kampus merdeka dan prestasi regional yang diraih di aplikasi PDDIKTI 3. Terus mendorong mahasiswa dalam mengikuti Kampus merdeka serta meningkatkan persiapan mahasiswa dalam mengikuti perlombaan-perlombaan minimal tingkat regional.', 'Adapun kendala yang dihadapi dalam mencapai IKU ini diantaranya: 1. adanya selisih tarikan data antara mahasiswa aktif yang ada di PDDIKTI dengan yang tampil di Aplikasi Sidakin 2. adanya data mahasiswa yang mengikuti kampus merdeka yang sudah terinputkan di PDDIKTI namun tidak tampil di Sidakin 3. masih banyaknya mahasiswa yang tidak lolos kegiatan Kampus merdeka 4. serta masih kurangnya persiapan mahasiswa dalam mengikuti perlombaan.', 'Adapun upaya tindak lanjut yang dilakukan dalam mengatasi kendala yang ada sesuai dengan apa yang dibahas dalam rapat pimpinan adalah 1. Menertipkan pelaporan data mahasiswa aktif, cuti, dan DO di Aplikasi PDDIKTI 2. memaksimalkan data isian di PDDIKTI, dan berkoordinasi dengan tim pengembang terkait tarikan data yang tidak sesuai 3. mendampingi mahasiswa dalam pendaftaran kegiatan di kampus merdekan 4. serta aktif mendorong mahasiswa untuk meningkatkan kompetensi dan aktif berpartisipasi dalam berbagai kompetisi, menugaskan dosen pembimbing untuk meningkatkan kompetensi mahasiswa serta mengalokasikan anggaran untuk lomba-lomba minimal tingkat regional'),
(96, 3, 5, 1, 'IKU ini merupakan data capaian untuk dosen yang berkegiatan tridharma di perguruan tinggi lain, bekerja sebagai praktisi di dunia industri, atau membimbing mahasiswa berkegiatan di luar program studi. Adapun untuk perhitungannya adalah jumlah dosen dengan NIDN yang berkegiatan tridharma di perguruan tinggi lain, bekerja sebagai praktisi di dunia industri, atau membimbing mahasiswa berkegiatan di luar program studi dibagi dengan jumlah dosen yang ber NIDN yang ada di Lembaga sesuai dengan data dosen yang ada di PDDIKTI. Dimana setiap kriterian tersebut akan dilakukan pembobotan sesuai dengan hitungan yang ada di Peraturan Direktur Jenderal Pendidikan Vokasi Nomor 62/D/M/2023 Tentang Pedoman Indikator Kinerja Utama Perguruan Tinggi Negeri Vokasi. Berdasarkan Kepmendikbudristek Nomor 210/M/2023 Tentang Indikator Kinerja Utama Perguruan Tinggi Negeri Vokasi Dan Lldikti bahwa dalam pengukuran TW 4 ini harus menggunakan data yang ditampilkan oleh Aplikasi Sidakin. Adapun berdasarkan data yang tampil di aplikasi Sidakin ada total 90 orang dosen yang menjadi pembagi untuk perhitungan IKU ini. Di TW 4 ini berdasarkan data yang ditampilakan aplikasi Sidakin, Poltesa hanya berhasil mencapai 10,56% dari yang ditargetkan di TW 4 sebesar 30%, dimana dari total 90 orang dosen yang ada hanya ada 6 orang dosen membina mahasiswa meraih prestasi, 2 orang dosen praktisi, 9 orang dosen yang mengajar di kampus lain, dan 2 orang yang melakukan penelitan di luar kampus. Data ini seharusnya bisa bertambah mengingat data prestasi yang didapat di tahun 2022 cukup lumayan seperti yang disampaikan di IKU 2 terkait prestasi mahasiswa, namun karena tarikan data dari aplikasi jadi tidak tahu dimana kendalanya. Adapun upaya yang telah dilakukan dalam mendukung IKU ini diantaranya: 1. mendorong para dosen untuk mengupdate data diri di sister 2. meningkatkan proses pembinaan ke mahasiswa, baik di bidang akademik maupun non akademik 3. Meningkatkan alokasi anggaran untuk pemenuhan persiapan dan keikutsertaan dalam lomba lomba.', 'Adapun kendala yang dihadapi diantaranya: 1. Adanya data yang tidak sinkron antara data inputan di PDDIKTI dengan yang ditampilkan di Sidakin 2. Kurangnya partisipasi dosen dalam mengupdate data diri terkait capaian IKU yang bisa menambah capaian di aplikasi Sister 3. Kurangnya persiapan lomba karena penyelenggaraan bersamaan dengan jadwal pengajaran dan beban administrasi lainnya di kampus', 'Adapun tindak lanjut yang dilakukan berdasarkan rapat pimpinan adalah: 1. Memaksimalkan isian data dan mengkoordinasikan kepada pihak pengembang terkait tarikan data 2. Terus menghimbau seluruh dosen untuk aktif melaporkan dan mengisikan data diri di aplikasi sister 3. Meminta dosen pendamping dan mahasiswa yang akan mengikuti lomba untuk mempersiapkan diri jauh jauh hari.'),
(97, 5, 5, 1, 'IKU ini merupakan data capaian untuk dosen tetap yang memiliki sertifikat kompetensi/profesi yang diakui oleh dunia usaha dan dunia industri dan pengajar yang berasal dari kalangan praktisi profesional, dunia usaha, atau dunia industri. Adapun cara perhitungannya adalah jumlah dosen yang yang memiliki sertifikat kompetensi/profesi yang diakui oleh dunia usaha dan dunia industri dan pengajar yang berasal dari kalangan praktisi profesional, dunia usaha, atau dunia industri dibagi dengan jumlah dosen yang ada di lembaga. Dimana setiap kriterian tersebut akan dilakukan pembobotan sesuai dengan hitungan yang ada di Peraturan Direktur Jenderal Pendidikan Vokasi Nomor 62/D/M/2023 Tentang Pedoman Indikator Kinerja Utama Perguruan Tinggi Negeri Vokasi. Berdasarkan Kepmendikbudristek Nomor 210/M/2023 Tentang Indikator Kinerja Utama Perguruan Tinggi Negeri Vokasi Dan Lldikti bahwa dalam pengukuran TW 4 ini harus menggunakan data yang ditampilkan oleh Aplikasi Sidakin. Adapun berdasarkan data yang tampil di aplikasi Sidakin ada total 90 orang dosen yang menjadi pembagi untuk perhitungan IKU ini. di tw 4 ini berdasarkan data yang ditampilakan aplikasi sidakin, poltesa hanya berhasil mencapai 16,89% dari yang ditargetkan di tw 4 sebesar 50%, dimana dari total 90 orang dosen yang ada hanya ada 24 orang dosen yang memiliki sertifikat kompetensi/profesi yang diakui oleh dunia usaha dan dunia industri. dan hanya ada 2 orang dosen yang pengajar yang berasal dari kalangan praktisi profesional, dunia industri, atau dunia kerja. Data capaian ini seharusnya bisa lebih mengingat lebih dari 70% dosen yang ada dipoltesa sudah memiliki sertifikat kompetensi/profisi namun tidak tertarik di aplikasi sister dan Sidakin. Adapun upaya yang telah dilakukan dalam mendukung IKU ini diantaranya: 1. para dosen mengikuti pelatihan dan uji kompetensi yang sesuai bidang terlebih lagi yang diselenggarakan dan dibiayai oleh pusat 2. melakukan tindak lanjut MOU terkait ketersediaan tenaga ahli dari industri untuk bisa mengajar di Poltesa.', 'Dalam mencapai IKU ini ada beberapa kendala: 1. banyak dosen yang tidak mengupdate data diri di aplikasi sister, khususnya mengenai sertifikasi kompetensi yang telah didapat 2. tidak tertariknya data secara keseluruhan ke aplikasi Sidakin 3. masih kurangnya jumlah pengajar yang berasal dari kalangan praktisi, dunia usaha atau dunia industri', 'Adapun tindak lanjut yang disampaikan pimpinan dalam rapat pengukuran ialah: 1. terus mendorong para dosen untuk melakukan update data diri atas setiap capaian sertifikasi kompetensi yang didapat 2. melakukan komunikasi lebih lanjut kepada pihak pengembang aplikasi 3. meningkatkan jumlah kerjasama yang menyasar ke hal pengajaran.'),
(98, 6, 5, 1, 'IKU ini merupakan data capaian untuk Jumlah keluaran dosen yang berhasil mendapat rekognisi internasional atau diterapkan oleh masyarakat/industri/pemerintah per jumlah dosen. Adapun cara perhitungannya adalah jumlah keluaran dosen yang berhasil mendapat rekognisi internasional atau diterapkan oleh masyarakat/industri/pemerintah dibagi dengan jumlah dosen tetap yang ada di Politeknik Negeri Sambas. Dimana setiap kriterian tersebut akan dilakukan pembobotan sesuai dengan hitungan yang ada di Peraturan Direktur Jenderal Pendidikan Vokasi Nomor 62/D/M/2023 Tentang Pedoman Indikator Kinerja Utama Perguruan Tinggi Negeri Vokasi. Berdasarkan Kepmendikbudristek Nomor 210/M/2023 Tentang Indikator Kinerja Utama Perguruan Tinggi Negeri Vokasi Dan Lldikti bahwa dalam pengukuran TW 4 ini harus menggunakan data yang ditampilkan oleh Aplikasi Sidakin. Adapun berdasarkan data yang tampil di aplikasi Sidakin ada total 90 orang dosen yang menjadi pembagi untuk perhitungan IKU ini. di tw 4 ini berdasarkan data yang ditampilakan aplikasi sidakin, poltesa hanya berhasil mencapai 57,11% dari yang ditargetkan di tw 4 sebesar 100%, dimana dari total 90 orang dosen yang ada hanya ada 65 orang dosen yang keluarannya berhasil mendapat rekognisi internasional atau diterapkan oleh masyarakat/industri/pemerintah, yaitu berupa publikasi karya terapan dan karya tulis ilmiah. Data ini seharusnya bisa lebih tinggi namun tidak terlaporkan, karena seluruh data capaian ini murni merupakan hasil inputan dosen di masing-masing akun sisternya. Adapun upaya yang telah dilakukan dalam mendukung IKU ini diantaranya: 1. meningkatkan kualitas keluaran hasil penelitian dan PKM dosen melalui skema-skema pendanaan internal dan eksternal 2. memberikan pelatihan kepada dosen melalui kegiatan Sehati Abdimas 3. mengingatkan kepada seluruh dosen agar mengupdate data diri atas hasil keluaran penelitian di aplikasi sister', 'Adapun kendala yang dihadapi diantaranya: 1. daya saing, kemampuan bahasa Inggris, dan biaya seringkali menjadi kendala partisipasi dalam konferensi internasional 2. hasil penelitian dan pengabdian dosen masih banyak yang belum diterapkan langsung dimasyarakat 3. masih kurangnya kedisiplinan dosen dalam melaporkan dan menginputkan data capaian pribadinya terkait hasil keluaran ini ke aplikasi Sister, sehingga data tersebut tidak tertarik dan terlaporkan di Sidakin.', 'Adapun tindak lanjut yang dilakukan berdasarkan hasil rapat pimpinan diantaranya: 1. memfasilitasi dosen dalam meningkatkan kemampuan berbahasa inggris dengan bantuan dan kerjasama dari UPT TIK, serta memberikan insentif dan bantuan untuk biaya jurnal dan konferensi internasional 2. mengoordinasikan penelitian dan pengabdian dosen agar lebih bermanfaat dan dapat diterapkan langsung dimasyarakat melalui seleksi proposal penelitian dan PKM yang dilakukan oleh P3M 3. memberikan himbauan kepada seluruh dosen untuk melaporkan dan menginputkan data capaian pribadinya terkait hasil keluaran ini ke aplikasi Sister.'),
(99, 7, 5, 1, 'iku ini merupakan data capaian untuk jumlah program studi s1 dan d4/d3/d2 yang melaksanakan kerja sama dengan mitra. adapun cara perhitungannya adalah jumlah program studi yang melaksanakan kerjasama dengan mitra dibagi dengan jumlah program studi yang ada di politeknik negeri sambas di kali 100%. Dimana setiap kriterian bentuk kerjasama tersebut akan dilakukan pembobotan sesuai dengan hitungan yang ada di Peraturan Direktur Jenderal Pendidikan Vokasi Nomor 62/D/M/2023 Tentang Pedoman Indikator Kinerja Utama Perguruan Tinggi Negeri Vokasi. Berdasarkan Kepmendikbudristek Nomor 210/M/2023 Tentang Indikator Kinerja Utama Perguruan Tinggi Negeri Vokasi Dan Lldikti bahwa dalam pengukuran TW 4 ini harus menggunakan data yang ditampilkan oleh Aplikasi Sidakin. Adapun berdasarkan data yang tampil di aplikasi Sidakin ada total 9 Program Studi yang menjadi pembagi untuk perhitungan IKU ini. Adapun sumber data yang digunakan adalah merupakan hasil inputan data kerjasama yang dilaporkan pada aplikasi mitreka yang dialirkan ke aplikasi sikerma. di tw 4 ini berdasarkan data yang ditampilakan aplikasi sidakin, poltesa berhasil mencapai 184,44% dari yang ditargetkan di tw 4 sebesar 100%, yang artinya keseluruhan Program Studi yang ada telah melaksanakan kerjasama dengan mitra dan memenuhi kriteria kerjasama yang diminta. Berdasarkan data yang ditampilkan di Sidakin total ada 15 Mitra yang telah sepakat menjalin kerjasama. Adapun upaya yang telah dilakukan dalam mendukung tercapainya IKU ini diantaranya: 1. melakukan penginputan ulang seluruh data kerjasama ke aplikasi Mitreka 2. melaksanakan beberapa MOU baik yang baru maupun MOU lama dengan penambahan berapa aktivitas yang mendukung IKU 3. penjajakan kerjasama kerjasama baru yang lebih luas baik didalam maupun diluar negeri', 'Adapun kendala utama yang dihadapi dalam mendukung IKU ini adalah: 1. terbatasnya jumlah industri yang ada didaerah kampus 2. masih belum maksimal dalam pemanfaatan bentuk kerjasama.', 'adapun solusi yang diusahakan saat ini adalah: 1. melakukan perluasan kerjasama diluar daerah 2. mendorong seluruh prodi memaksimalkan pelaksanaan bentuk kerjasama '),
(100, 8, 5, 1, 'IKU ini merupakan data capaian untuk jumlah mata kuliah S1 dan D4/D3/D2 yang menggunakan metode pembelajaran pemecahan kasus (case method) atau pembelajaran kelompok berbasis projek (team-based project) sebagai sebagian bobot evaluasi. Adapun cara perhitungannya adalah jumlah mata kuliah S1 dan D4/D3/D2 yang menggunakan metode pembelajaran pemecahan kasus (case method) atau pembelajaran kelompok berbasis projek (team-based project) sebagai sebagian bobot evaluasi dibagi dengan jumlah mata kuliah yang ada di Politeknik Negeri Sambas di kali 100%. Berdasarkan Kepmendikbudristek Nomor 210/M/2023 Tentang Indikator Kinerja Utama Perguruan Tinggi Negeri Vokasi Dan Lldikti bahwa dalam pengukuran TW 4 ini harus menggunakan data yang ditampilkan oleh Aplikasi Sidakin. Adapun berdasarkan data yang tampil di aplikasi Sidakin total ada 306 mata kuliah yang ada yang nantinya akan menjadi pembagi data capaian iku ini dan seluruh data ini dilaporkan melalui PDDIKTI. Adapaun di TW 4 untuk IKU ini Poltesa hanya tercapai 14,05% dari yang ditargetkan sebesar 40%. dimana dari total 306 mata kuliah yang ada di 9 prodi, total hanya ada 43 mata kuliah yang masuk dalam kategori IKU ini. Adapun upaya yang dilakukan dalam mendukung IKU ini diantaranya: 1. mengajukan pembukaan priode pelaporan PDDIKTI 2. melakukan rapat bersama dengan seluruh Prodi dan operator PDDIKTI terkait pengisian data evaluasi pembelajara 3. perbaikan buku pedoman akademik khususnya terkait pelaksanaan PBL', 'singkatnya waktu persiapan dan waktu berkoordinasi dengan mata kuliah lainnya maupun dengan PBL bersama prodi lainnya serta kendala dalam memperbaharui (updating) kasus - kasus menjadi tantantan tersendiri bagi dosen maupun mahasiswa.', 'Perencanaan dan pemetaan project di awal semester dengan goal atau target yang jelas, fokus, dan terukur serta koordinasi dengan industri dan mitra prodi untuk updating berbabgai real-life kasus yang perlu dicarikan solusinya dalam proses pembelajaran mahasiswa'),
(101, 9, 5, 1, 'IKU ini merupakan data capaian untuk jumlah program studi S1 dan D4/D3/D2 yang memiliki akreditasi atau sertifikat internasional yang diakui pemerintah. Adapun cara perhitungannya adalah jumlah program studi S1 dan D4/D3/D2 yang memiliki akreditasi atau sertifikat internasional yang diakui pemerintah dibagi dengan jumlah program studi yang ada di Politeknik Negeri Sambas di kali 100%. Berdasarkan Kepmendikbudristek Nomor 210/M/2023 Tentang Indikator Kinerja Utama Perguruan Tinggi Negeri Vokasi Dan Lldikti bahwa dalam pengukuran TW 4 ini harus menggunakan data yang ditampilkan oleh Aplikasi Sidakin. Adapun berdasarkan data yang tampil di aplikasi Sidakin ada total 9 Program Studi yang menjadi pembagi untuk perhitungan IKU ini. untuk IKu Persentase program studi S1 dan D4/D3/D2 yang memiliki akreditasi yang diakui pemerintah atau sertifikat internasional yang diakui pemerintah di TW 4 ini capaian Poltesa masih 0% dari yang ditargetkan 2,5%. Untuk kondisi sekarang 9 prodi di Poltesa baru terakreditasi nasional dari BAN PT dengan status 5 prodi 6 dan sisa nya masih C. untuk saat ini prodi masih melakukan identifikasi dan Pemenuhan standar dan persyaratan Prodi akreditasi/sertifikasi yang diakui dan ada beberapa prodi yang lagi persiapan untuk reakreditasi. Selain itu juga bagian mutu terus belajar dan mengikuti kegiatan yang berkaitan dengan standar-standar akreditasi ataupun sertifikat internasional yang diakui oleh pemerintah serta melaksanakan beberapa pelatihan untuk teknisi dan dosen dengan pelatihan yang berstandar ISO. Untuk saat ini berapa prodi sedang persiapan untuk reakreditasi, dan yang terbaru yaitu prodi TMM yang baru saja keluar hasil akreditasinya dengal perolehan Baik Sekali.', 'kendala yang dihadapi masih sama yaitu belum terpenuhinya persyaratan untuk mendapatkan akreditasi atau sertifikasi internasonal yang diakui pemerintah.', 'Pimpinan terus memacu dan memotivasi prodi untuk memenuhi standar/persyaratan akreditasi/sertifikasi serta memberikan dukungan anggaran untuk kegiatan seminar dan pelatihan untuk prodi agar bisa mencapai IKU ini.'),
(107, 1, 1, 2, 'IKU ini merupakan data capaian untuk lulusan yang mendapatkan pekerjaan dengan masa tunggu kurang dari 6 (enam) bulan dan gaji lebih dari 1,2 (satu koma dua) kali Upah Minimum Regional (UMR), lulusan yang melanjutkan studi di Perguruan Tinggi Negeri (PTN) Akademik Mendapatkan surat penerimaan untuk melanjutkan proses pembelajaran di program studi S2/S2 terapan, S3/S3 terapan di dalam negeri atau luar negeri dalam jangka waktu kurang dari 12 (dua belas) bulan setelah lulus serta lulusan yang mulai bekerja dalam waktu kurang dari 6 (enam) bulan setelah lulus dan berpenghasilan lebih dari 1,2 (satu koma dua) kali UMR. untuk capaian di TW 1 ini Poltesa berhasil mencapai 20.84% dari yang ditargetkan di TW 1 sebesar 20%. Dari total 379 orang lulusan dari 9 prodi yang di wisuda pada akhir tahun 2022 kemarin ada sebanyak 59 orang yang telah berhasil mendapatkan pekerjaan, 1 orang yang melanjutkan studi, dan ada 19 orang yang menjadi wiraswasta. Adapun upaya yang telah dilakukan dalam mencapai IKK ini diantaranya: 1. Melakukan Bembekalan kepada wisudawan terkait pentingnya memberikan data di aplikasi tracer study 2. Meningkatkan pelayanan pada aplikasi tracer study 3. Menjadikan bukti pengisian tracer study sebagai syarat dalam pengambilan ijazah 4. Mengaktifkan grub WA alumni', 'Kendala yang dialami dalam melakukan pengukuran pada IKK ini diantaranya: 1. Adanya sedikit masalah pada aplikasi tracer study yang disebabkan oleh pemindahan server sehingga ada jeda waktu yang menyebabkan tim gagal dalam menarik data 2. Masih banyak alumni yang belum mengambil ijazah 3. Adanya alumni yang lost contak atau berganti nomor', 'Adapun tindak lanjut yang dilakukan dalam mengatasi kendala-kendala tersebut sesuai dengan arahan pimpinan pada saat rapat pengukuran kinerja diantaranya: 1. Meminta tim developer dan tim TIK untuk segera menyelesaikan proses pemindahan server aplikasi tracer study, sehingga pengisian data dan penarikan data dari aplikasi tracer bisa maksimal 2. Melalui WA grub alumni, para kaprodi diminta untuk menghimbau alumni untuk segera melakukan pengambilan ijazah dan meminta melakukan update jika ada perubahan nomor Hp dan status pekerjaan atau usaha.'),
(108, 2, 1, 2, 'IKU ini merupakan data capaian untuk Mahasiswa yang mendapatkan paling sedikit 20 (dua puluh) sks dari kegiatan di luar kampus (dengan dosen pembimbing), sesuai dengan Buku Panduan Merdeka Belajar serta Berprestasi dalam kompetisi atau lomba paling rendah tingkat nasional. Adapun cara perhitungannya adalah jumlah mahasiswa yang Mahasiswa yang mendapatkan paling sedikit 20 (dua puluh) sks dari kegiatan di luar dan Berprestasi dalam kompetisi atau lomba paling rendah tingkat nasional dibagi dengan jumlah mahasiswa aktif ditahun 2023 di kali 100%. untuk capaian di TW 1 ini Poltesa berhasil mencapai 0,45 % dari yang ditargetkan sebesar 0,25%. untuk saat ini berdasarkan data pada PDDIKTI ada sekitar 1.980 mahasiswa aktif yang ada di lingkungan Poltesa. dari 1.980 mahasiswa aktif tersebut ada sebanyak 8 orang mahasiswa yang telah menghabiskan paling sedikit 20 sks diluar kampus. Yaitu 1 orang dari prodi APK atas nama Bintang Rahasia Ramadhan Magang di luar negeri di Restoran Pengolahan Produk Perikanan, 2 orang dari prodi MBP atas nama Juanda dan Agung Dirgantoro Mandala Putra Magang dan Studi Independen Bersertifikat Batch 4 (magang kampus merdeka, 3 orang dari prodi TME atas nama Ahmad Hidayad, Budi Marli, dan Umar Sihab yang magang diluar kurikulum di Magang di PT. PANP, 1 orang dari prodi TMM atas nama Fitria dalam kegiatan pertukaran Pelajar antar provinsi dan 1 orang dari prodi TMP atas nama Rendy Maulana Program Markija Berdaya. sedangkan untuk mahasiswa yang meraih prestasi minimal tingkat nasional untuk di TW 1 berhasil dicapai oleh 1 orang mahasiswa prodi akuntansi atas nama Nur Aulia, yang berhasil menjadi pemenang dan berhak lolos dalam acara Pertukaran Pemuda Antar Negara utusan Provinsi Kalimantan Barat ke Negara Australia.', 'Adapun kendala yang dihadapi dalam mencapai IKK ini diantaranya: 1. Motivasi mahasiswa ke luar daerah atau kemauan mengikuti kegiatan luar kampus masih rendah sehingga partisipasi dalam pendaftaran program Kampus Merdeka masih rendah 2. Perbedaan persepsi dosen setiap prodi mengenai konversi nilai masih menjadi kendala sehingga langkah mengikutsertakan mahasiswa dalam MBKM masih tersendat. Ketegasan direktur sangat diharapkan dalam kondisi ini dengan menerbitkan perdir program MBKM (POLTESA belum memutuskan mengikuti program Kampus Merdeka). Hingga saat ini hanya segelintir dosen yang berbekal semangat untuk mendukung serta membimbing mahasiswa mengikuti program MBKM demi mendukung PK direktur 3. Awal tahun belum ada lomba yang digelar (belum dapat diikuti) serta Kendala pendanaan karena lokasi kompetisi rata-rata berada di luar Pulau Kalimantan dengan biaya pendaftaran yang cukup besar pula, Kendala waktu karena waktu persiapan seringkali mepet dan mahasiswa tidak bisa memenuhi standar minimal untuk dapat mengikuti kompetisi.', 'Adapun upaya tindak lanjut yang dilakukan dalam mengatasi kendala yang ada sesuai dengan apa yang dibahas dalam rapat pimpinan adalah : 1. Sosialisasi da pengarahan untuk memberikan motivasi kepada mahasiswa dengan kendali melalui dosen pembimbing akademik 2. Segera membuat panduan merdeka belajar serta menyemarakkan gema merdeka belajar yang disosialisasikan kepada dosen dan tendik agar menjadi habituasi baru di lingkungan kampus 3. aktif mendorong mahasiswa untuk meningkatkan kompetensi dan aktif berpartisipasi dalam berbagai kompetisi, menugaskan dosen pembimbing untuk meningkatkan kompetensi mahasiswa serta mengikuti kompetisi yang diadakan daring, serta mengalokasikan anggaran untuk lomba-lomba tingkat nasional maupun internasional.'),
(115, 1, 2, 2, 'IKU ini merupakan data capaian untuk lulusan yang mendapatkan pekerjaan dengan masa tunggu kurang dari 6 (enam) bulan dan gaji lebih dari 1,2 (satu koma dua) kali Upah Minimum Regional (UMR), lulusan yang melanjutkan studi di Perguruan Tinggi Negeri (PTN) Akademik Mendapatkan surat penerimaan untuk melanjutkan proses pembelajaran di program studi S2/S2 terapan, S3/S3 terapan di dalam negeri atau luar negeri dalam jangka waktu kurang dari 12 (dua belas) bulan. untuk capaian di TW 2 ini Poltesa berhasil mencapai 30,34% dari yang ditargetkan di TW 2 sebesar 33%. Dari total 379 orang lulusan dari 9 prodi yang di wisuda pada akhir tahun 2022 kemarin total ada sebanyak 115 orang yang masuk dalam kriteria IKU ini, dengan rincian ada sebanyak 95 orang yang telah berhasil mendapatkan pekerjaan, 1 orang yang melanjutkan studi, dan ada 19 orang yang menjadi wiraswasta. Adapun khusus di TW 2 ini hanya ada penambahan 32 orang lulusan yang berhasil mendapat pekerjaan seiring dengan perbaikan pada aplikasi tracer study dimana di tw 1 kemarin masih terdapat kendala untuk di TW 2 ini sudah kembali normal. Sedangkan untuk yang berwiraswasta dan melanjutkan studi tidak ada penambahan. Berikut nama nama alumni dan tempat ia bekerja: -Prodi AGB ada 3 orang yaitu Serin Oktavia (Balai Penyuluhan Pertanian), Levi Yanti (PNM) dan Norma Wati (PT Laik) -Prodi AIP ada 8 orang yaitu Sanertin, Diana, Jodi Pratama (PT. Unicoco Idustries Indonesia), Salindri (Djarum Retail Patnership Rama), Ami (Kantor Desa Tengguli), Susi Anisah (Badan Penyuluh Pertanian), Arifah Madani (PT. Aditama Yogyakarta), Ratih Cinliberty (SMK Negeri Semparuk sebagai Guru Produktif di bidang Olahan Pangan) -Prodi APK ada 1 orang yaitu Fajar Muslim (PT. Hutan Ketapang Industri) -Prodi MBP ada 4 orang yaitu Salendri (PT. Sumber Alfaria Trijaya, Tbk), Nurhasanah (PT. Saloinyan), NIKUen (Kantor Desa Temajuk), Nur Azira (Kantor Pegadaian) -Prodi TME ada 2 orang yaitu Dede Nur Iksan (PT. Bringin Inti Teknologi bit.corp), Widi Ariski (PT. Karya Boga Mitra KBM Sambas) -Prodi TMP ada 1 orang atas nama Ricki (PT Nindya Karya) -Prodi MIF ada 11 orang yaitu atas nama Mohammad Fazrul (Pondok Digital Aghnia), Ria (Smkn 1 selakau timur), Nunung Lestari (Badan Pusat Statistik), Sahid Sadiqi (PT Borneo Lancar Abadi), Shinta Nabila ( Sdn 02 galing), Ira Pratiwi (RSU Harapan Bersama), Tia Astuti (Nashpetshop), NUNUNG LESTARI (Badan Pusat Statistik), Dewi purwasih dan Yudi (PT Sumber Alfaria Trijaya Tbk/ Alfamart) -Prodi AKP ada 6 orang yaitu atas nama Andrianto (Dinas Koperasi, Usaha Kecil, Menengah, Perindustrian dan Perdagangan Kab Sambas) Deli (BAKEUDA Sambas), Annen (PT. Sambas Alam Lestari), Selpiani (Pendata Lapangan Regsosek BPS Sambas), Nely (PT. Sambas Alam Lestari) dan Dea Andini (CV. Ayracard Barokah). Adapun upaya yang telah dilakukan dalam mencapai IKU ini diantaranya: 1. Melakukan Pembekalan kepada wisudawan dan calon wisudawan terkait pentingnya memberikan data di aplikasi tracer study 2. Terus mengaktifkan grub WA alumni 3. Meningkatkan pengelolaan aplikasi tracer study.', 'Kendala yang dialami dalam melakukan pengukuran pada IKU ini diantaranya: 1. Untuk beberapa prodi lowongan cukup terbuka lebar karena banyak perusahaan yang memerlukan tenaga kerja bidang perawatan perbaikan, hanya saja beberapa perusahaan memerlukan pekerja yang telah memiliki pengalaman kerja 2. Masih banyak alumni yang belum mengambil ijazah dan mengisi data di tracer study 3. Adanya alumni yang lost contak atau berganti nomor.', 'Adapun tindak lanjut yang dilakukan dalam mengatasi kendala-kendala tersebut sesuai dengan arahan pimpinan pada saat rapat pengukuran kinerja diantaranya: 1. Meningkatkan kemampuan mahasiswa semasa kuliah seperti mendapatkan pengalaman dan sertifikat magang, serta dalam ilmu kewirausahaan. Agar ketika lulus kuliah tidak perlu mencari pekerjaan, namun justru dapat mencipatakan lapangan pekerjaan baru dengan berwirausaha 2. Melalui WA grub alumni, para kaprodi diminta untuk menghimbau alumni untuk segera melakukan pengambilan ijazah dan meminta melakukan update jika ada perubahan nomor Hp dan status pekerjaan atau usaha 3. melakukan perisapan pembekalan untuk calon wisudawan yang akan di wisuda bulan agustus di tahun ini'),
(116, 2, 2, 2, 'IKU ini merupakan data capaian untuk Mahasiswa yang mendapatkan paling sedikit 20 (dua puluh) sks dari kegiatan di luar kampus (dengan dosen pembimbing), sesuai dengan Buku Panduan Merdeka Belajar serta Berprestasi dalam kompetisi atau lomba paling rendah tingkat nasional. Adapun cara perhitungannya adalah jumlah mahasiswa yang Mahasiswa yang mendapatkan paling sedikit 20 (dua puluh) sks dari kegiatan di luar dan Berprestasi dalam kompetisi atau lomba paling rendah tingkat nasional dibagi dengan jumlah mahasiswa aktif ditahun 2023 di kali 100%. untuk capaian di TW 2 ini Poltesa berhasil mencapai 0,96 % dari yang ditargetkan sebesar 3,75%. untuk saat ini berdasarkan data pada PDDIKTI ada sekitar 1.980 mahasiswa aktif yang ada di lingkungan Poltesa. dari 1.980 mahasiswa aktif tersebut total sampai dengan TW 2 ini ada sebanyak 13 orang mahasiswa yang telah menghabiskan paling sedikit 20 sks diluar kampus bertambah 5 orang dari capaian di TW 1 yaitu 4 orang dari Prodi MBP atas nama Marhapida Rabbani (IISMA 2023), Rian Adi Wijatmiko (IISMA 2023), Nur Zaki dan Didik Dwi Wahyudi (Pertukaran Mahasiswa Merdeka Polibatam) dan ada 1 orang dari prodi AKP yaitu atas nama Rinda Nur Atika (Kampus Mengajar Kemdikbud tahun 2022 penempatan di SMP Muhammadiyah 3 Pontianak). sedangkan untuk mahasiswa yang meraih prestasi minimal tingkat nasional sampai dengan di TW 2 berhasil dicapai oleh 10 orang mahasiswa. Khusus di TW 2 ada penambahan sebanyak 5 orang yaitu dari prodi AGB 1 orang yaitu atas nama Adrianto (Juara 3 Tilawah Putra pada MTQ Politeknik Tingkat Nasional Tahun 2023/1444 H), dari prodi AIP 1 orang yaitu atas nama Era Sagita (lolos seleksi ProgramPertukaran Pemuda Antar Provinsi 2023), dari prodi MBP ada 1 orang yaitu atas nama Nur Izatul Egiantri (Finalis Putri Remaja Nusantara 2023), dari prodi TME ada 2 orang yaitu atas nama Abdul Rahman (Juara 2 Tartil Putra Kategori Qiraah Politeknik Pertanian Negeri Pangkajene Kepulauan), Alkadri (Putra Nusantara Photogenic 2023). Adapun upaya yang telah dilakukan dalam mendukung tercapainya IKU ini diantaranya: 1. dengan mengikutkan serta mendorong mahasiswa untuk mengikuti magang mereka 2. Selalu memonitoring kegiatan kompetisi Nasional yang dapat diikuti mahasiswa 3. Mahasiswa didoronng mengikuti kompetisi sesuai minat dan bakat masing-masing. Saat ini sudah dilakukan pemilihan mahasiswa yang akan mewakili Poltesa dalam ajang kompetisi pariwisata nasional.', 'Adapun kendala yang dihadapi dalam mencapai IKU ini diantaranya: 1. Masih belum banyak lomba yang digelar (belum dapat diikuti) serta Kendala pendanaan karena lokasi kompetisi rata-rata berada di luar Pulau Kalimantan dengan biaya pendaftaran yang cukup besar pula, Kendala waktu karena waktu persiapan seringkali mepet dan mahasiswa tidak bisa memenuhi standar minimal untuk dapat mengikuti kompetisi 2. Perbedaan persepsi dosen setiap prodi mengenai konversi nilai masih menjadi kendala sehingga langkah mengikutsertakan mahasiswa dalam MBKM masih tersendat. Ketegasan direktur sangat diharapkan dalam kondisi ini dengan menerbitkan perdir program MBKM (POLTESA belum memutuskan mengikuti program Kampus Merdeka). Hingga saat ini hanya segelintir dosen yang berbekal semangat untuk mendukung serta membimbing mahasiswa mengikuti program MBKM demi mendukung PK direktur 3. Motivasi mahasiswa ke luar daerah atau kemauan mengikuti kegiatan luar kampus masih rendah sehingga partisipasi dalam pendaftaran program Kampus Merdeka masih rendah', 'Adapun upaya tindak lanjut yang dilakukan dalam mengatasi kendala yang ada sesuai dengan apa yang dibahas dalam rapat pimpinan adalah: 1. aktif mendorong mahasiswa untuk meningkatkan kompetensi dan aktif berpartisipasi dalam berbagai kompetisi, menugaskan dosen pembimbing untuk meningkatkan kompetensi mahasiswa serta mengikuti kompetisi yang diadakan daring, serta mengalokasikan anggaran untuk lomba-lomba tingkat nasional maupun internasional 2. Segera membuat panduan merdeka belajar serta menyemarakkan gema merdeka belajar yang disosialisasikan kepada dosen dan tendik agar menjadi habituasi baru di lingkungan kampus 3. Sosialisasi dan pengarahan untuk memberikan motivasi kepada mahasiswa dengan kendali melalui dosen pembimbing akademik'),
(117, 1, 2, 2, 'IKU ini merupakan data capaian untuk dosen yang berkegiatan tridharma di kampus lain, di QS100 berdasarkan bidang ilmu (QS100 by subject), bekerja sebagai praktisi di dunia industri, atau membina mahasiswa yang berhasil meraih prestasi paling rendah tingkat nasional dalam 5 (lima) tahun terakhir. pada TW 2 Poltesa berhasi mencapai 36,47 % dari yang ditargetkan di TW 2 sebesar 38%, dimana dari total 85 orang dosen yang ada di Poltesa ada 2 orang dosen yang berkegiatan tridarma dikampus lain yaitu atas nama Muhammad Usman sebagai Dosen Part Time Sekolah Tinggi Ilmu Kesehatan Prima Indonesia dan Eliza Noviriani sebagai Editor dan Reviewer Exsternal Jurnal GLOW (Jurnal Pengabdian Kepada Masyarakat) STIE SULTAN AGUNG Sumatera Utara. untuk dosen yang bekerja sebagai praktisi di dunia industri ada 2 orang yaitu atas nama Fathushahib dan Heldi Hastriyandi sebagai TRAINER untuk Kegiatan Program Vocational School Graduate Academy (VSGA) skema Junior Network Administrator. sedangkan untuk dosen yang membina mahasiswa yang berhasil meraih prestasi paling rendah tingkat nasional dalam 5 tahun terakhir ada penambahan sebanyak 5 orang (yang diklaim hanya 4) dari capaian di TW 1, yaitu atas nama Uray Dian Novita yaitu membina Adrianto Juara 3 Tilawah Putra pada MTQ Politeknik Tingkat Nasional Tahun 2023/1444 H, dari prodi AIP 1 orang yaitu atas nama Andi maryam membina mahasiswa lolos seleksi Program Pertukaran Pemuda Antar Provinsi 2023, dari prodi MBP ada 1 orang yaitu atas nama Nur Asti Fatihah (tidak diklaim) yang berhasil membina Finalis Putri Remaja Nusantara 2023), dari prodi TME ada 2 orang yaitu atas nama Erwin yang berhasil membina mahasiswa Juara 2 Tartil Putra Kategori Qiraah Politeknik Pertanian Negeri Pangkajene Kepulauan, Leo Dedy Anjiu yang berhasil membina mahasiswa lolos Putra Nusantara Photogenic 2023) Adapun upaya yang telah dilakukan dalam mendukung IKU ini diantaranya: 1. Beberapa dosen yang sedang proses menunggu penugasan mengajar sebgai Tutor dan Pengampu Mata Kuliah di Universitas Terbuka 2. Para dosen terus mencari informasi terkait pendaftaran untuk berkegiatan (meneliti atau mengikuti kegiatan pendidikan di QS 100) 3. Meningkatkan alokasi anggaran untuk pemenuhan persiapan dan keikutsertaan dalam lomba lomba nasional dan internasional.', 'Adapun kendala yang dihadapi diantaranya: 1. Beban kerja dosen di homebase sudah banyak bahkan berlebih, sehingga berkegiatan di kampus lain tidak menjadi prioritas bagi dosen 2. Kurangnya persiapan ketika penyelenggaraan bersamaan dengan jadwal pengajaran dan beban administrasi lainnya di kampus 3. Kegiatan tridarma perguruan tinggi yang menjadi kewajiban dosen membuat jadwal dosen cukup padat sehingga kegiatan menjadi praktisi dengan periode kerja tertentu belum bisa terlaksana. Keterlibatan dosen di DUDI lebih banyak bersifat sementara atau sebagai narasumber saja 4. Kendala pendanaan karena lokasi kompetisi rata-rata berada di luar Pulau Kalimantan dengan biaya pendaftaran yang cukup besar pula, serta Kendala waktu karena waktu persiapan seringkali mepet dan mahasiswa tidak bisa memenuhi standar minimal untuk dapat mengikuti kompetisi.', 'Adapun tindak lanjut yang dilakukan berdasarkan rapat pimpinan adalah: 1. Menindaklanjuti PKS dan MoU dengan kampus lain dalam pelaksanaan tridarma terutama penelitian dan pengabdian kepada masyarakat 2. peningkatan kemampuan berbahasa Inggris bagi dosen, Pengaturan jadwal dosen untuk mendaftar short course atau kegiatan lain di QS 100 3. Memperluas dan memperkuat jejaring dengan DUDI bidang pariwisata dan hospitality agar menambah kesempatan dosen untuk berkegiatan sebagai praktisi 4. mengikuti kompetisi yang diadakan daring, persiapan intensif melalui bimbingan dosen serta menambah anggaran untuk mengikuti perlombaan.'),
(121, 1, 5, 2, 'IKU ini merupakan data capaian untuk lulusan yang Memiliki pekerjaan dalam rentang waktu 12 (dua belas) bulan setelah lulus baik di perusahaan swasta, termasuk perusahaan nasional, perusahaan multinasional, perusahaan rintisan (startup company) Usaha Mikro, Kecil dan Menengah (UMKM), dan lain-lain organisasi nirlaba institusi/organisasi multilateral lembaga pemerintah atau Badan Usaha Milik Negara (BUMN)/Badan Usaha Milik Daerah (BUMD), lulusan Melanjutkan proses pembelajaran di program studi profesi, S1/D4 terapan, S2/S2 terapan, S3/S3 terapan di dalam negeri atau luar negeri dalam rentang waktu kurang dari 12 (dua belas) bulan setelah lulus, serta lulusan yang menjadi wirausaha baik sebagai sebagai pendiri (founder)atau pasangan pendiri (co-founder,l perusahaan atau pekerja lepas (freelancer). Untuk perhitungannya adalah jumlah lulusan yang memiliki pekerjaan, lulusan yang melanjutkan studi di Perguruan Tinggi dan lulusan menjadi wiraswasta dibagi dengan jumlah wisudawan. Dimana setiap kriterian tersebut akan dilakukan pembobotan sesuai dengan hitungan yang ada di Peraturan Direktur Jenderal Pendidikan Vokasi Nomor 62/D/M/2023 Tentang Pedoman Indikator Kinerja Utama Perguruan Tinggi Negeri Vokasi. Berdasarkan Kepmendikbudristek Nomor 210/M/2023 Tentang Indikator Kinerja Utama Perguruan Tinggi Negeri Vokasi Dan Lldikti bahwa dalam pengukuran TW 4 ini harus menggunakan data yang ditampilkan oleh Aplikasi Sidakin. Adapun lulusan Politeknik Negeri Sambas yang menjadi dasar perhitungan pengukuran TW 4 ini adalah lulusan tahun 2021 dengan jumlah lulusan sebanyak 348 orang dengan minimal responden sebanyak 60% dari jumlah lulusan. Untuk capaian IKU ini di TW 4 berdasarkan hasil dari aplikasi Sidakin, Politeknik Negeri Sambas berhasil mencapai skor 65,19% dari yang ditargetkan di TW 4 sebesar 60%. Dari total 348 orang lulusan dari 9 prodi yang di wisuda pada akhir tahun 2021 kemarin total ada sebanyak 253 orang yang masuk dalam kriteria dan pembobotan IKU ini, dengan rincian ada sebanyak 126 orang yang telah berhasil mendapatkan pekerjaan, 1 orang yang melanjutkan studi, dan ada 126 orang yang menjadi wiraswasta. Adapun upaya yang telah dilakukan dalam mendukung IKU ini diantaranya: 1. Melakukan bembekalan kepada calon wisudawan setiap angkatan terkait pentingnya pengisian dan update data alumni 2. Meningkatkan jumlah bantuan kewirausahaan mahasiswa 3. Melakukan ekspo produk kewirausaan mahasiswa 4. Meningkatkan jumlah kerja sama, khususnya dalam hal rekrutmen lulusan untuk bekerja 5. Melakukan rapat bersama tim Tracer dan seluruh prodi terkait perubahan pola pelaporan dan data alumni yang digunakan 6. Menghubungi para alumni untuk melakukan pengisian dan update data di aplikasi tracer.', 'Kendala yang dialami dalam melakukan pengukuran pada IKU ini diantaranya: 1. Seringnya terjadi gangguan pada aplikasi tracer 2. Masih terbatasnya pihak industri/lembaga yang berkomitmen dalam pengrekrutan alumni 3. Banyak wirausaha mahasiswa yang tidak dilanjutkan ketika sudah lulus 4. Adanya alumni yang lost contact atau berganti nomor.', 'Adapun tindak lanjut yang dilakukan dalam mengatasi kendala-kendala tersebut sesuai dengan arahan pimpinan pada saat rapat pengukuran kinerja diantaranya: 1. Terus berkoordinasi dengan tim pengembang aplikasi serta menginformasikan kepada para alumni terkait aplikasi tracer 2. Melalu tim kerjasama, pimpinan menekankan untuk meningkatkan kualitas dan kuantitas kerja sama dengan mitra, khususnya terkait informasi lowongan dan rekrutmen lulusan 3. Melakukan pembinaan dan pendampingan kewirausahaan mahasiswa sampai dengan pasca lulus 4. Melalui WA grub alumni, para staff prodi meminta melakukan update jika ada perubahan nomor Hp dan status pekerjaan atau usaha.');
INSERT INTO `keterangan` (`id_ket`, `id_iku`, `id_triwulan`, `id_prodi`, `progres`, `kendala`, `strategi`) VALUES
(122, 2, 5, 2, 'IKU ini merupakan data capaian untuk Mahasiswa yang menghabiskan sampai dengan 20 (dua puluh) sks per semester di luar program studi dengan batas minimal yang dapat dihitung adalah paling sedikit 10 (sepuluh) sks untuk mahasiswa S1/D4/D3 yang mana kegiatan-Kegiatannya bisa berupa magang atau praktik kerja, proyek di desa, mengajar di sekolah, pertukaran pelajar, penelitian atau riset, kegiatan wirausaha, studi atau proyek independen, proyek kemanusiaan, bela negara dimana kegiatannya boleh dikombinasikan dan dihitung kumulatif. Serta mahasiswa yang Berprestasi dalam kompetisi atau lomba pada peringkat juara I - III pada kompetisi Internasional, Nasional maupun provinsi, Memiliki karya yang digunakan dunia usaha, industri dan masyarakat atau Mendapatkan sertifikasi kompetensi internasional. Adapun cara perhitungannya adalah jumlah mahasiswa aktif yang menghabiskan sampai dengan 20 (dua puluh) sks per semester di luar program studi dan jumlah mahasiswa yang Berprestasi dalam kompetisi atau lomba dibagi dengan jumlah mahasiswa aktif. Dimana setiap kriterian tersebut akan dilakukan pembobotan sesuai dengan hitungan yang ada di Peraturan Direktur Jenderal Pendidikan Vokasi Nomor 62/D/M/2023 Tentang Pedoman Indikator Kinerja Utama Perguruan Tinggi Negeri Vokasi. Berdasarkan Kepmendikbudristek Nomor 210/M/2023 Tentang Indikator Kinerja Utama Perguruan Tinggi Negeri Vokasi Dan Lldikti bahwa dalam pengukuran TW 4 ini harus menggunakan data yang ditampilkan oleh Aplikasi Sidakin. Adapun data yang digunakan adalah data mahasiswa aktif yang ada di PDDIKTI untuk periode Genap 2021/2022 dan Ganjil 2022/2023 yaitu sebanyak 2.231 orang. untuk capaian di TW 4 ini Poltesa berhasil mencapai 24,57% dari yang ditargetkan sebesar 30%. Berdasarkan data pada PDDIKTI dari 2.331 mahasiswa aktif tersebut total sampai dengan TW 4 ini ada sebanyak 391 orang Mahasiswa Menjalankan Magang Wajib Diluar Prodi dan ada sebanyak 46 orang mahasiswa yang berhasil meraih prestasi baik di level Internasional, Nasional dan Regional. Sedangkan untuk mahasiswa yang mengikuti Kampus merdeka berdasarkan data yang ditampilkan sidakin adalah 0, padahal menurut data capaian dan inputan di aplikasi PDDIKTI ada sekitar 120 orang mahasiswa. Adapun upaya yang telah dilakukan dalam mendukung tercapainya IKU ini diantaranya: 1. Mengajukan pembukaan priode untuk pelaporan PDDIKTI 2. Melakukan pendataan ulang dan penginputan terkait kegiatan kampus merdeka dan prestasi regional yang diraih di aplikasi PDDIKTI 3. Terus mendorong mahasiswa dalam mengikuti Kampus merdeka serta meningkatkan persiapan mahasiswa dalam mengikuti perlombaan-perlombaan minimal tingkat regional.', 'Adapun kendala yang dihadapi dalam mencapai IKU ini diantaranya: 1. adanya selisih tarikan data antara mahasiswa aktif yang ada di PDDIKTI dengan yang tampil di Aplikasi Sidakin 2. adanya data mahasiswa yang mengikuti kampus merdeka yang sudah terinputkan di PDDIKTI namun tidak tampil di Sidakin 3. masih banyaknya mahasiswa yang tidak lolos kegiatan Kampus merdeka 4. serta masih kurangnya persiapan mahasiswa dalam mengikuti perlombaan.', 'Adapun upaya tindak lanjut yang dilakukan dalam mengatasi kendala yang ada sesuai dengan apa yang dibahas dalam rapat pimpinan adalah 1. Menertipkan pelaporan data mahasiswa aktif, cuti, dan DO di Aplikasi PDDIKTI 2. memaksimalkan data isian di PDDIKTI, dan berkoordinasi dengan tim pengembang terkait tarikan data yang tidak sesuai 3. mendampingi mahasiswa dalam pendaftaran kegiatan di kampus merdekan 4. serta aktif mendorong mahasiswa untuk meningkatkan kompetensi dan aktif berpartisipasi dalam berbagai kompetisi, menugaskan dosen pembimbing untuk meningkatkan kompetensi mahasiswa serta mengalokasikan anggaran untuk lomba-lomba minimal tingkat regional'),
(123, 3, 5, 2, 'IKU ini merupakan data capaian untuk dosen yang berkegiatan tridharma di perguruan tinggi lain, bekerja sebagai praktisi di dunia industri, atau membimbing mahasiswa berkegiatan di luar program studi. Adapun untuk perhitungannya adalah jumlah dosen dengan NIDN yang berkegiatan tridharma di perguruan tinggi lain, bekerja sebagai praktisi di dunia industri, atau membimbing mahasiswa berkegiatan di luar program studi dibagi dengan jumlah dosen yang ber NIDN yang ada di Lembaga sesuai dengan data dosen yang ada di PDDIKTI. Dimana setiap kriterian tersebut akan dilakukan pembobotan sesuai dengan hitungan yang ada di Peraturan Direktur Jenderal Pendidikan Vokasi Nomor 62/D/M/2023 Tentang Pedoman Indikator Kinerja Utama Perguruan Tinggi Negeri Vokasi. Berdasarkan Kepmendikbudristek Nomor 210/M/2023 Tentang Indikator Kinerja Utama Perguruan Tinggi Negeri Vokasi Dan Lldikti bahwa dalam pengukuran TW 4 ini harus menggunakan data yang ditampilkan oleh Aplikasi Sidakin. Adapun berdasarkan data yang tampil di aplikasi Sidakin ada total 90 orang dosen yang menjadi pembagi untuk perhitungan IKU ini. Di TW 4 ini berdasarkan data yang ditampilakan aplikasi Sidakin, Poltesa hanya berhasil mencapai 10,56% dari yang ditargetkan di TW 4 sebesar 30%, dimana dari total 90 orang dosen yang ada hanya ada 6 orang dosen membina mahasiswa meraih prestasi, 2 orang dosen praktisi, 9 orang dosen yang mengajar di kampus lain, dan 2 orang yang melakukan penelitan di luar kampus. Data ini seharusnya bisa bertambah mengingat data prestasi yang didapat di tahun 2022 cukup lumayan seperti yang disampaikan di IKU 2 terkait prestasi mahasiswa, namun karena tarikan data dari aplikasi jadi tidak tahu dimana kendalanya. Adapun upaya yang telah dilakukan dalam mendukung IKU ini diantaranya: 1. mendorong para dosen untuk mengupdate data diri di sister 2. meningkatkan proses pembinaan ke mahasiswa, baik di bidang akademik maupun non akademik 3. Meningkatkan alokasi anggaran untuk pemenuhan persiapan dan keikutsertaan dalam lomba lomba.', 'Adapun kendala yang dihadapi diantaranya: 1. Adanya data yang tidak sinkron antara data inputan di PDDIKTI dengan yang ditampilkan di Sidakin 2. Kurangnya partisipasi dosen dalam mengupdate data diri terkait capaian IKU yang bisa menambah capaian di aplikasi Sister 3. Kurangnya persiapan lomba karena penyelenggaraan bersamaan dengan jadwal pengajaran dan beban administrasi lainnya di kampus', 'Adapun tindak lanjut yang dilakukan berdasarkan rapat pimpinan adalah: 1. Memaksimalkan isian data dan mengkoordinasikan kepada pihak pengembang terkait tarikan data 2. Terus menghimbau seluruh dosen untuk aktif melaporkan dan mengisikan data diri di aplikasi sister 3. Meminta dosen pendamping dan mahasiswa yang akan mengikuti lomba untuk mempersiapkan diri jauh jauh hari.'),
(124, 1, 3, 2, 'IKU ini merupakan data capaian untuk lulusan yang mendapatkan pekerjaan dengan masa tunggu kurang dari 6 (enam) bulan dan gaji lebih dari 1,2 (satu koma dua) kali Upah Minimum Regional (UMR), lulusan yang melanjutkan studi di Perguruan Tinggi Negeri (PTN) Akademik Mendapatkan surat penerimaan untuk melanjutkan proses pembelajaran di program studi S2/S2 terapan, S3/S3 terapan di dalam negeri atau luar negeri dalam jangka waktu kurang dari 12 (dua belas) bulan. untuk capaian di TW 3 ini Poltesa berhasil mencapai 38,26% dari yang ditargetkan di TW 3 sebesar 48%. Dari total 379 orang lulusan dari 9 prodi yang di wisuda pada akhir tahun 2022 kemarin total ada sebanyak 145 orang yang masuk dalam kriteria IKU ini, dengan rincian ada sebanyak 121 orang yang telah berhasil mendapatkan pekerjaan, 2 orang yang melanjutkan studi, dan ada 22 orang yang menjadi wiraswasta. Adapun khusus di TW 3 ini hanya ada penambahan 26 orang lulusan yang berhasil mendapat pekerjaan seiring dengan perbaikan pada aplikasi tracer study dimana di tw 1 dan tw 2 kemarin. Sedangkan untuk yang berwiraswasta ada penambahan 3 orang dan melanjutkan studi ada penambahan 1 orang. Adapun upaya yang telah dilakukan dalam mencapai IKU ini diantaranya: 1. Melakukan sharing dan diskusi dengan satker lain terkait stragegi yang dilakukan dalam peningkatan capaian pengisian tracer study 2. Terus mengaktifkan grub WA alumni 3. Meningkatkan pengelolaan aplikasi tracer study.', 'Kendala yang dialami dalam melakukan pengukuran pada IKU ini diantaranya: 1. Untuk beberapa prodi lowongan cukup terbuka lebar karena banyak perusahaan yang memerlukan tenaga kerja bidang perawatan perbaikan, hanya saja beberapa perusahaan memerlukan pekerja yang telah memiliki pengalaman kerja 2. Masih banyak alumni yang belum mengambil ijazah serta mengisi dan mengupdate data di tracer study 3. Adanya alumni yang lost contact atau berganti nomor.', 'Adapun tindak lanjut yang dilakukan dalam mengatasi kendala-kendala tersebut sesuai dengan arahan pimpinan pada saat rapat pengukuran kinerja diantaranya: 1. Meningkatkan kemampuan mahasiswa semasa kuliah seperti mendapatkan pengalaman dan sertifikat magang, serta dalam ilmu kewirausahaan. Agar ketika lulus kuliah tidak perlu mencari pekerjaan, namun justru dapat mencipatakan lapangan pekerjaan baru dengan berwirausaha 2. Melalui WA grub alumni, para kaprodi diminta untuk menghimbau alumni untuk segera melakukan pengambilan ijazah dan meminta melakukan update jika ada perubahan nomor Hp dan status pekerjaan atau usaha 3. Akan mencoba memaksimalkan ikatan alumni dan kontak alumni yang aktif, yang nantinya akan dilakukan pendataan secara langsung dengan cara dihubungi satu persatu oleh staff akademik dan staff prodi'),
(125, 2, 3, 2, 'IKU ini merupakan data capaian untuk Mahasiswa yang mendapatkan paling sedikit 20 (dua puluh) sks dari kegiatan di luar kampus (dengan dosen pembimbing), sesuai dengan Buku Panduan Merdeka Belajar serta Berprestasi dalam kompetisi atau lomba paling rendah tingkat nasional. Adapun cara perhitungannya adalah jumlah mahasiswa yang Mahasiswa yang mendapatkan paling sedikit 20 (dua puluh) sks dari kegiatan di luar dan Berprestasi dalam kompetisi atau lomba paling rendah tingkat nasional dibagi dengan jumlah mahasiswa aktif ditahun 2023 di kali 100%. untuk capaian di TW 3 ini Poltesa berhasil mencapai 3,03% dari yang ditargetkan sebesar 5,75%. untuk saat ini berdasarkan data pada PDDIKTI ada sekitar 1.980 mahasiswa aktif yang ada di lingkungan Poltesa. dari 1.980 mahasiswa aktif tersebut total sampai dengan TW 3 ini ada sebanyak 47 orang mahasiswa yang telah menghabiskan paling sedikit 20 sks diluar kampus bertambah 34 orang dari capaian di TW 2, yaitu 20 orang dari Prodi AIP, ada 2 orang dari prodi AGB, 3 orang dari prodi MBP, 2 orang dari prodi MIF, 3 orang dari Prodi TMM dan 4 orang dari prodi AKP 3 orang. sedangkan untuk mahasiswa yang meraih prestasi minimal tingkat nasional sampai dengan di TW 3 berhasil dicapai oleh 13 orang mahasiswa. Khusus di TW 3 ada penambahan sebanyak 7 orang yaitu dari prodi AIP 1 orang, dan dari prodi AKP ada 6 orang. Adapun untuk data mahasiswa yang meraih prestasi adalah sebagai berikut : Nur Aulia Perserta Pertukaran Pemuda Antar Negara (PPAN) utusan Provinsi Kalimantan Barat ke Australia tahun 2023 Zarina Juara 1 Kategori Teresponsif Lomba Poster Olimpiade Akuntansi Vokasi (OAV) 6 Nasional 2023 Dhiemas Permana Juanda Juara 1 Kategori Teresponsif Lomba Poster Olimpiade Akuntansi Vokasi (OAV) 6 Nasional 2023 dan Juara 2 Kategori Terdramatis Lomba Konten Video Olimpiade Akuntansi Vokasi (OAV) 6 Nasional 2023 Anwar Juara 3 Kategori Tersolutif Konten Video Olimpiade Akuntansi Vokasi (OAV) 6 Nasional 2023 dan Aldo Juara 3 Kategori Tersolutif Konten Video Olimpiade Akuntansi Vokasi (OAV) 6 Nasional 2023. Untuk saat ini Mahasiswa masih mengikuti program MBKM 2023 hingga semester ganjil ini berakhir. Beberapa progrm flagship MBKM sudah mulai dibuka. Adapun upaya yang telah dilakukan dalam mendukung tercapainya IKU ini diantaranya: 1. dengan mengikutkan serta mendorong mahasiswa untuk mengikuti magang mereka 2. Selalu memonitoring kegiatan kompetisi Nasional yang dapat diikuti mahasiswa 3. Mahasiswa didorong mengikuti kompetisi sesuai minat dan bakat masing-masing. Saat ini sudah dilakukan pemilihan mahasiswa yang akan mewakili Poltesa dalam ajang kompetisi nasional yang tersisa', 'Adapun kendala yang dihadapi dalam mencapai IKU ini diantaranya: 1. Masih belum banyak lomba yang digelar (belum dapat diikuti) serta Kendala pendanaan karena lokasi kompetisi rata-rata berada di luar Pulau Kalimantan dengan biaya pendaftaran yang cukup besar pula, Kendala waktu karena waktu persiapan seringkali mepet dan mahasiswa tidak bisa memenuhi standar minimal untuk dapat mengikuti kompetisi 2. Perbedaan persepsi dosen setiap prodi mengenai konversi nilai masih menjadi kendala sehingga langkah mengikutsertakan mahasiswa dalam MBKM masih tersendat. Ketegasan direktur sangat diharapkan dalam kondisi ini dengan menerbitkan Perdir program MBKM (POLTESA belum memutuskan mengikuti program Kampus Merdeka). Hingga saat ini hanya segelintir dosen yang berbekal semangat untuk mendukung serta membimbing mahasiswa mengikuti program MBKM demi mendukung PK direktur 3. Motivasi mahasiswa ke luar daerah atau kemauan mengikuti kegiatan luar kampus masih rendah sehingga partisipasi dalam pendaftaran program Kampus Merdeka masih rendah', 'Adapun upaya tindak lanjut yang dilakukan dalam mengatasi kendala yang ada sesuai dengan apa yang dibahas dalam rapat pimpinan adalah: 1. aktif mendorong mahasiswa untuk meningkatkan kompetensi dan aktif berpartisipasi dalam berbagai kompetisi, menugaskan dosen pembimbing untuk meningkatkan kompetensi mahasiswa serta mengikuti kompetisi yang diadakan daring, serta mengalokasikan anggaran untuk lomba-lomba tingkat nasional maupun internasional 2. Segera membuat panduan merdeka belajar serta menyemarakkan gema merdeka belajar yang disosialisasikan kepada dosen dan tendik agar menjadi habituasi baru di lingkungan kampus 3. Sosialisasi dan pengarahan untuk memberikan motivasi kepada mahasiswa dengan kendali melalui dosen pembimbing akademik'),
(126, 3, 3, 2, 'IKU ini merupakan data capaian untuk dosen yang berkegiatan tridharma di kampus lain, di QS100 berdasarkan bidang ilmu (QS100 by subject), bekerja sebagai praktisi di dunia industri, atau membina mahasiswa yang berhasil meraih prestasi paling rendah tingkat nasional dalam 5 (lima) tahun terakhir. pada TW 3 Poltesa berhasi mencapai 41,17 % dari yang ditargetkan di TW 3 sebesar 49%, dimana dari total 85 orang dosen yang ada di Poltesa ada 3 orang dosen yang berkegiatan tridarma dikampus lain, bertambah 1 orang dari capaian sampai dengan TW 2 yaitu atas nama Pande Putu Santoso sebagai Tutor pada Pokjar Abdurachman-Senujuh Kab. Sambas, Universitas Terbuka. untuk dosen yang bekerja sebagai praktisi di dunia industri ada 2 orang yaitu atas nama Iman Syahrizal sebagai pengajar dalam kegiatan bimbingan teknis WUB IKM bengkel las di Kabupaten Sambas dan Ari Rianto, ST, MT sebagai sebagai pengajar dalam kegiatan bimbingan teknis WUB IKM bengkel las di Kabupaten Singkawang. sedangkan untuk dosen yang membina mahasiswa yang berhasil meraih prestasi paling rendah tingkat nasional dalam 5 tahun terakhir tidak ada penambahan dari capaian TW sebelumnya. Adapun upaya yang telah dilakukan dalam mendukung IKU ini diantaranya: 1. Beberapa dosen yang sedang proses menunggu penugasan mengajar sebgai Tutor dan Pengampu Mata Kuliah di Universitas Terbuka 2. Para dosen terus mencari informasi terkait pendaftaran untuk berkegiatan (meneliti atau mengikuti kegiatan pendidikan di QS 100) 3. Meningkatkan alokasi anggaran untuk pemenuhan persiapan dan keikutsertaan dalam lomba lomba nasional dan internasional.', 'Adapun kendala yang dihadapi diantaranya: 1. Beban kerja dosen di homebase sudah banyak bahkan berlebih, sehingga berkegiatan di kampus lain tidak menjadi prioritas bagi dosen 2. Kurangnya persiapan ketika penyelenggaraan bersamaan dengan jadwal pengajaran dan beban administrasi lainnya di kampus 3. Kegiatan tridarma perguruan tinggi yang menjadi kewajiban dosen membuat jadwal dosen cukup padat sehingga kegiatan menjadi praktisi dengan periode kerja tertentu belum bisa terlaksana. Keterlibatan dosen di DUDI lebih banyak bersifat sementara atau sebagai narasumber saja 4. Kendala pendanaan karena lokasi kompetisi rata-rata berada di luar Pulau Kalimantan dengan biaya pendaftaran yang cukup besar pula, serta Kendala waktu karena waktu persiapan seringkali mepet dan mahasiswa tidak bisa memenuhi standar minimal untuk dapat mengikuti kompetisi.', 'Adapun tindak lanjut yang dilakukan berdasarkan rapat pimpinan adalah: 1. Menindaklanjuti PKS dan MoU dengan kampus lain dalam pelaksanaan tridarma terutama penelitian dan pengabdian kepada masyarakat 2. peningkatan kemampuan berbahasa Inggris bagi dosen, Pengaturan jadwal dosen untuk mendaftar short course atau kegiatan lain di QS 100 3. Memperluas dan memperkuat jejaring dengan DUDI bidang pariwisata dan hospitality agar menambah kesempatan dosen untuk berkegiatan sebagai praktisi 4. mengikuti kompetisi yang diadakan daring, persiapan intensif melalui bimbingan dosen serta menambah anggaran untuk mengikuti perlombaan.');

